from AlgorithmImports import *
from datetime import timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_today = False
        self.equity_cleanup_ticket = None

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, self.consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value
        else:
            self.previous_fast = None
            self.previous_slow = None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            end_time = bar.EndTime.time()
            if time(9, 45) <= end_time <= time(14, 30):
                self.pending_signal = True

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_symbol is not None:
            self.ProcessExpirationAndTimeStop(slice)
            self.ProcessProfitTarget(slice)

        if self.pending_signal:
            self.pending_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.no_entry_today:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.IsEntryOrderOpen():
            return

        if self.spy.Symbol not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = slice.Bars[self.spy.Symbol].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = list(slice.OptionChains)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain:
                expiry = contract.Symbol.ID.Date.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry >= minimum_expiry
                    and contract.Strike >= 1.01 * spy_price
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible call contract.")
            return

        nearest_expiry = min(
            contract.Symbol.ID.Date.date() for contract in contracts
        )

        candidates = [
            contract for contract in contracts
            if contract.Symbol.ID.Date.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiry={nearest_expiry}; strike={selected.Strike}"
        )

    def ProcessProfitTarget(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.IsExitOrderOpen():
            return

        contract = self.GetHeldContract(slice)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("profit target")

    def ProcessExpirationAndTimeStop(self, slice):
        if self.held_symbol is None:
            return

        security = self.Securities[self.held_symbol]
        expiry_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.no_entry_today = True
            self.SubmitExit("expiration protection")
            return

        previous_trading_day = expiry_date - timedelta(days=1)
        while not security.Exchange.Hours.IsDateOpen(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("pre-expiration time stop")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.IsExitOrderOpen():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}; symbol={self.held_symbol}")

    def GetHeldContract(self, slice):
        if self.held_symbol is None:
            return None

        for chain in slice.OptionChains:
            if self.held_symbol in chain.Contracts:
                return chain.Contracts[self.held_symbol]

        return None

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in {
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        }

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in {
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        }

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity == 0:
            return

        if (
            self.equity_cleanup_ticket is None
            or self.equity_cleanup_ticket.Status not in {
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.UpdateSubmitted
            }
        ):
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.equity_cleanup_ticket = self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="unexpected exercise or assignment"
            )
            self.no_entry_today = True

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment received.")
        self.no_entry_today = True
        self.HandleUnexpectedEquityPosition()

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.FillQuantity != 0:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = (
                        self.entry_ticket.AverageFillPrice
                        if self.entry_ticket.AverageFillPrice > 0
                        else order_event.FillPrice
                    )
                    self.Debug(
                        f"Entry filled: {self.held_symbol}; "
                        f"price={self.entry_price}"
                    )

                if order_event.Status in {
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                }:
                    if order_event.Status != OrderStatus.Filled:
                        self.Debug("Entry order did not fill.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(f"Exit filled: {order_event.Symbol}")
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status in {
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                }:
                    self.exit_ticket = None
