```python
from AlgorithmImports import *

from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False
        )
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False
        )
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_key = None
        self.bucket_bars = []
        self.current_slice = None

        self.held_symbol = None
        self.entry_ticket = None
        self.entry_price = None
        self.exit_ticket = None

        self.no_entry_date = None
        self.previous_session_by_expiry = {}

    def OnData(self, slice: Slice):
        self.current_slice = slice
        now = self.Time
        today = now.date()

        # Remove any SPY equity created by unexpected exercise or assignment.
        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY equity position; liquidating")
            self.Liquidate(
                self.spy,
                "Unexpected exercise/assignment cleanup"
            )

        self.ProcessExpirationAndTimeStop(now)
        self.ProcessProfitTarget(slice)

        if not slice.Bars.ContainsKey(self.spy):
            return

        bar = slice.Bars[self.spy]
        bar_time = bar.Time.replace(tzinfo=None)

        if bar_time.time() < time(9, 30) or bar_time.time() >= time(16, 0):
            return

        if self.no_entry_date == today:
            return

        bucket_key = (
            bar_time.date(),
            bar_time.hour,
            (bar_time.minute // 5) * 5
        )

        if self.bucket_key is not None and bucket_key != self.bucket_key:
            self.FinishBucket()
            self.bucket_bars = []

        if self.bucket_key != bucket_key:
            self.bucket_key = bucket_key

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            self.FinishBucket()
            self.bucket_bars = []

    def FinishBucket(self):
        if self.bucket_key is None or len(self.bucket_bars) != 5:
            return

        bars = self.bucket_bars

        expected_times = [
            datetime(
                self.bucket_key[0],
                self.bucket_key[1],
                self.bucket_key[2]
            ) + timedelta(minutes=i)
            for i in range(5)
        ]

        actual_times = [
            bar.Time.replace(tzinfo=None)
            for bar in bars
        ]

        # Reject incomplete or irregular five-minute intervals.
        if actual_times != expected_times:
            return

        self.closes.append(float(bars[-1].Close))

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        fast = sum(values[-5:]) / 5.0
        slow = sum(values) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = bars[-1].EndTime.replace(tzinfo=None)

        eligible_time = (
            time(9, 45) <= end_time.time() <= time(14, 30)
        )

        if bullish_crossover and eligible_time:
            self.TryEnter(self.current_slice, float(bars[-1].Close))

    def TryEnter(self, slice: Slice, spy_price: float):
        if self.held_symbol is not None:
            return

        if self.IsOrderOpen(self.entry_ticket):
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()

                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                    and contract.Strike >= 1.01 * spy_price
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no qualifying contract")
            return

        nearest_expiry = min(
            contract.Expiry.date()
            for contract in candidates
        )

        candidates = [
            contract
            for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish crossover call entry"
        )

        self.Debug("Call entry submitted: " + str(selected.Symbol))

    def ProcessProfitTarget(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        contract = None

        for chain in slice.OptionChains.Values:
            if chain.Contracts.ContainsKey(self.held_symbol):
                contract = chain.Contracts[self.held_symbol]
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit(
                "50% profit target",
                cancel_existing_exit=True
            )

    def ProcessExpirationAndTimeStop(self, now: datetime):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if now.date() >= expiry_date:
            self.no_entry_date = now.date()
            self.SubmitExit("Expiration protection")
            return

        previous_session = self.previous_session_by_expiry.get(expiry_date)

        if previous_session is None:
            trading_days = self.TradingCalendar.GetTradingDays(
                expiry_date - timedelta(days=14),
                expiry_date - timedelta(days=1)
            )

            previous_session = max(
                day.Date.date()
                if hasattr(day.Date, "date")
                else day.Date
                for day in trading_days
            )

            self.previous_session_by_expiry[expiry_date] = previous_session

        if (
            now.date() == previous_session
            and now.time() >= time(15, 45)
        ):
            self.SubmitExit("Expiration-eve time stop")

    def SubmitExit(self, tag: str, cancel_existing_exit: bool = False):
        if self.held_symbol is None:
            return

        if self.IsOrderOpen(self.entry_ticket):
            return

        if self.IsOrderOpen(self.exit_ticket):
            if not cancel_existing_exit:
                return

            self.Transactions.CancelOrder(
                self.exit_ticket.OrderId,
                "Replacing open exit order"
            )

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=tag
        )

        self.Debug("Exit submitted: " + tag)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled at " + str(self.entry_price)
                )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: " + str(order_event.Symbol)
                )
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None

        if (
            hasattr(order_event, "IsAssignment")
            and order_event.IsAssignment
        ):
            self.Debug(
                "Unexpected option exercise/assignment; liquidating SPY"
            )
            if self.Portfolio[self.spy].Invested:
