            self.expiration_processing_today = False

        self._process_expiration()
        self._evaluate_exit(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._add_minute_bar(bar, slice)

    def _add_minute_bar(self, bar: TradeBar, slice: Slice):
        minute_start = bar.Time.replace(second=0, microsecond=0)

        session_start = time(9, 30)
        session_end = time(16, 0)

        if minute_start.time() < session_start or minute_start.time() >= session_end:
