            self._discard_incomplete_bucket()

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        self.bucket_bars[minute_start] = bar

        # A five-minute bar ending at 09:35 consists of minute bars 09:30–09:34.
        if bar.EndTime.minute % 5 != 0:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.bucket_bars for t in expected_times):
