            return

        bars = [self.bucket_bars[t] for t in expected_times]
        close = bars[-1].Close

        self._update_moving_averages(close)

        bar_end_time = self.bucket_start + timedelta(minutes=5)
        self._evaluate_entry_signal(bar_end_time, slice)

        self.bucket_bars.clear()
        self.bucket_start = None

    def _discard_incomplete_bucket(self):
        self.bucket_bars.clear()
        self.bucket_start = None

    def _update_moving_averages(self, close: float):
        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = sum(self.fast_window) / self.fast_period
        current_slow = sum(self.slow_window) / self.slow_period

        if self.previous_fast is not None and self.previous_slow is not None:
            self._previous_fast_for_signal = self.previous_fast
            self._previous_slow_for_signal = self.previous_slow
        else:
            self._previous_fast_for_signal = None
            self._previous_slow_for_signal = None

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        self._current_fast_for_signal = current_fast
        self._current_slow_for_signal = current_slow

