        selected = self._select_call_contract(slice)

        if selected is None:
            self.Debug(
                f"{self.Time}: skipped call selection after bullish crossover"
            )
            return

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _select_call_contract(self, slice: Slice):
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            return None

        contracts = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                expiry = contract.Expiry
                expiry_date = expiry.date()

                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                    and contract.Strike >= 1.01 * spy_price
                ):
                    contracts.append(contract)

        if not contracts:
            return None

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        same_expiry = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        return min(
            same_expiry,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_contract is None or self.entry_price is None:
            return

        if not self.Portfolio[self.held_contract].Invested:
            return

        if self._order_is_open(self.exit_ticket):
            return

        quote = self._find_contract_in_slice(slice, self.held_contract)

        if quote is not None:
            bid = quote.BidPrice
            ask = quote.AskPrice

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0

                if midpoint >= 1.50 * self.entry_price:
                    self._submit_exit("50% profit target")
                    return

        if self.held_expiry is None:
            return

        expiry_date = self.held_expiry.date()
        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration-eve time stop")

    def _process_expiration(self):
        if self.held_contract is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.expiration_processing_today = True

            if self.Portfolio[self.held_contract].Invested:
                self._submit_exit("expiration protection")

    def _submit_exit(self, reason: str):
        if self.held_contract is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        if self._order_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Exit requested while entry order was open")

        quantity = self.Portfolio[self.held_contract].Quantity

        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_contract,
                -quantity,
                tag=reason
            )
            self.Debug(
                f"{self.Time}: submitted option exit for "
                f"{self.held_contract} ({reason})"
            )

    def _find_contract_in_slice(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = datetime.combine(
            date_value - timedelta(days=1),
            time(0, 0)
        )

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.IsAssignment:
            self._handle_assignment(order_event)
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.FillQuantity != 0
            and order_event.FillPrice > 0
        ):
            order = self.Transactions.GetOrderById(order_event.OrderId)

            self.held_contract = order.Symbol
            self.held_expiry = order.Symbol.ID.Date
            self.entry_price = order_event.FillPrice

            self.Debug(
                f"{self.Time}: entered {self.held_contract} "
                f"at filled price {self.entry_price}"
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                f"{self.Time}: exited {order_event.Symbol} "
                f"at filled price {order_event.FillPrice}"
            )

            self.held_contract = None
            self.held_expiry = None
            self.entry_price = None
            self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self._handle_assignment(assignment_event)

    def _handle_assignment(self, assignment_event):
        self.expiration_processing_today = True

        self.Debug(
            f"{self.Time}: unexpected exercise or assignment for "
            f"{assignment_event.Symbol}; liquidating SPY equity"
        )

        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected assignment cleanup"
            )

        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
