from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(0), timedelta(days=730))
        )
        self.option_symbol = option.Symbol

        self.closes = []
        self.previous_averages = None

        self.minute_bucket = []
        self.bucket_start = None

        self.entry_ticket = None
        self.pending_entry_symbol = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.no_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, data: Slice):
        today = self.Time.date()

        # Unexpected exercise or assignment may create SPY shares.
        if self.Portfolio[self.spy].Invested:
            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                can_submit = (
                    self.equity_liquidation_ticket is None
                    or self.equity_liquidation_ticket.Status
                    in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid)
                )
                if can_submit:
                    self.Debug(
                        "Unexpected SPY exercise/assignment; liquidating equity"
                    )
                    self.equity_liquidation_ticket = self.MarketOrder(
                        self.spy,
                        -quantity,
                        tag="Unexpected exercise/assignment"
                    )

        if (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Invested
        ):
            expiration = self.held_symbol.ID.Date.date()

            if today >= expiration:
                self.no_entry_date = today
                self._liquidate_option("Expiration processing")

            elif (
                today == expiration - timedelta(days=1)
                and self.Time.hour == 15
                and self.Time.minute == 45
            ):
                self._liquidate_option("Expiration eve time stop")

            else:
                self._check_profit_target(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._accept_minute(spy_bar, data)

    def _accept_minute(self, bar, data):
        timestamp = bar.Time

        if timestamp.hour < 9:
            return
        if timestamp.hour == 9 and timestamp.minute < 31:
            return
        if timestamp.hour > 16:
            return

        is_boundary = timestamp.minute % 5 == 1

        if not self.minute_bucket:
            if not is_boundary:
                return

            self.bucket_start = timestamp
            self.minute_bucket = [bar]
            return

        expected = self.minute_bucket[-1].Time + timedelta(minutes=1)

        # Any missing minute invalidates the partial five-minute bar.
        if timestamp != expected or is_boundary:
            self.minute_bucket = []
            self.bucket_start = None

            if is_boundary:
                self.bucket_start = timestamp
                self.minute_bucket = [bar]

            return

        self.minute_bucket.append(bar)

        if len(self.minute_bucket) == 5:
            close = self.minute_bucket[-1].Close
            end_time = self.bucket_start + timedelta(minutes=4)

            self.minute_bucket = []
            self.bucket_start = None

            self._process_five_minute_close(end_time, close, data)

    def _process_five_minute_close(self, end_time, close, data):
        self.closes.append(close)

        if len(self.closes) < 20:
            return

        fast = sum(self.closes[-5:]) / 5.0
        slow = sum(self.closes[-20:]) / 20.0

        bullish_crossover = False
        if self.previous_averages is not None:
            previous_fast, previous_slow = self.previous_averages
            bullish_crossover = (
                previous_fast <= previous_slow
                and fast > slow
            )

        self.previous_averages = (fast, slow)

        eligible_time = (
            datetime(1900, 1, 1, 9, 45).time()
            <= end_time.time()
            <= datetime(1900, 1, 1, 14, 30).time()
        )

        if bullish_crossover and eligible_time:
            self._try_enter(data)

    def _try_enter(self, data):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Invested
        ):
            return

        if (
            self.entry_ticket is not None
            and self.entry_ticket.Status
            not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid)
        ):
            return

        if data is None or not data.OptionChains:
            self.Debug("Skipped call selection: no option chain")
            return

        eligible_contracts = []

        for chain in data.OptionChains.Values:
            for contract in chain:
                expiration = contract.Expiry.date()

                if expiration >= today + timedelta(days=7):
                    eligible_contracts.append((expiration, contract))

        if not eligible_contracts:
            self.Debug(
                "Skipped call selection: no expiration at least seven days out"
            )
            return

        selected_expiration = min(
            expiration for expiration, _ in eligible_contracts
        )

        spy_price = self.Securities[self.spy].Price

        candidates = [
            contract
            for expiration, contract in eligible_contracts
            if (
                expiration == selected_expiration
                and contract.Right == OptionRight.Call
                and contract.Strike >= 1.01 * spy_price
            )
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.pending_entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )

        self.Debug("Call entry submitted: " + str(selected.Symbol))

    def _check_profit_target(self, data):
        if self.entry_price is None:
            return

        if (
            self.exit_ticket is not None
            and self.exit_ticket.Status
            not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid)
        ):
            return

        quote = data.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason):
        if self.held_symbol is None:
            return

        if not self.Portfolio[self.held_symbol].Invested:
            return

        if (
            self.exit_ticket is not None
            and self.exit_ticket.Status
            not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid)
        ):
            return

        self.Transactions.CancelOpenOrders(self.held_symbol)

        quantity = self.Portfolio[self.held_symbol].Quantity

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug("Call exit submitted: " + reason)

