from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol

        # Broad weekly universe covering the required expirations and strikes.
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)

        self.bucket_start = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.entry_expiry = None

        self.entry_block_date = None

    def OnData(self, data):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._process_expiration(current_date)

        if self.held_symbol is not None:
            self._evaluate_profit_target(data)
            self._evaluate_time_stop(current_date)

        if not data.Bars.ContainsKey(self.spy):
            return

        bar = data.Bars[self.spy]
        bar_time = bar.Time.replace(second=0, microsecond=0)

        # Only regular-session SPY minute bars participate in consolidation.
        if bar_time.time() < datetime.strptime("09:30", "%H:%M").time():
            return
        if bar_time.time() >= datetime.strptime("16:00", "%H:%M").time():
            return

        bucket_start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start
        elif bucket_start != self.bucket_start:
            self._finalize_five_minute_bar(data)
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = bar

    def _finalize_five_minute_bar(self, data):
        if self.bucket_start is None:
            return

        times = sorted(self.bucket_bars.keys())

        # Do not use incomplete or gapped five-minute intervals.
        complete = (
            len(times) == 5 and
            all(
                times[i] - times[i - 1] == timedelta(minutes=1)
                for i in range(1, len(times))
            )
        )

        if not complete:
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in times]
        close = float(bars[-1].Close)

        previous_fast = None
        previous_slow = None
        if len(self.fast_window) == 5:
            previous_fast = sum(self.fast_window) / 5.0
        if len(self.slow_window) == 20:
            previous_slow = sum(self.slow_window) / 20.0

        self.fast_window.append(close)
        self.slow_window.append(close)

        if len(self.fast_window) == 5 and len(self.slow_window) == 20:
            current_fast = sum(self.fast_window) / 5.0
            current_slow = sum(self.slow_window) / 20.0

            bar_end = self.bucket_start + timedelta(minutes=5)
            end_time = bar_end.time()

            eligible_time = (
                datetime.strptime("09:45", "%H:%M").time()
                <= end_time
                <= datetime.strptime("14:30", "%H:%M").time()
            )

            bullish_crossover = (
                previous_fast is not None and
                previous_slow is not None and
                previous_fast <= previous_slow and
                current_fast > current_slow
            )

            if bullish_crossover and eligible_time:
                self._evaluate_entry(data)

        self.bucket_bars = {}

    def _evaluate_entry(self, data):
        current_date = self.Time.date()

        if self.entry_block_date == current_date:
            return
        if self.held_symbol is not None:
            return
        if self._is_open(self.entry_ticket):
