        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )
        self.option_symbol = self.spy_option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_end = None
        self.current_bucket = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None

        self.no_entry_today = False
        self.expiration_processed_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Immediately remove any SPY equity created by unexpected exercise or assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position detected; liquidating."
            )
            self.Liquidate(self.spy, "Unexpected exercise or assignment")
            self.no_entry_today = True

        self._process_expiration_rules(current_date)

        if self._has_option_holding():
            self._evaluate_option_exit(slice)

        if self.no_entry_today:
            return

        if self.spy not in slice.Bars:
            return

        spy_bar = slice.Bars[self.spy]
        self._update_five_minute_bar(spy_bar)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_time = self.Time.time()

        # Regular-session SPY minute bars only.
        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        minute_end = self.Time.replace(second=0, microsecond=0)

        # Buckets are aligned to New York clock boundaries:
        # 09:31-09:35 => bar ending 09:35, etc.
        end_minute = ((minute_end.minute - 30 + 4) // 5) * 5 + 30
        bucket_end = minute_end.replace(minute=0) + timedelta(minutes=end_minute)

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
        elif bucket_end != self.current_bucket_end:
            self._complete_bucket()
            self.current_bucket_end = bucket_end
            self.current_bucket = {}

        self.current_bucket[minute_end] = minute_bar

    def _complete_bucket(self):
        if self.current_bucket_end is None:
            return

        bucket_end = self.current_bucket_end
        expected_times = [
            bucket_end - timedelta(minutes=offset)
            for offset in range(5, 0, -1)
        ]

        # Missing minute data means the five-minute bar is not valid.
        if any(timestamp not in self.current_bucket for timestamp in expected_times):
            self.current_bucket = {}
            return

        five_minute_close = self.current_bucket[expected_times[-1]].Close
        self.closes.append(float(five_minute_close))

        if len(self.closes) < self.slow_period:
            self.current_bucket = {}
            return

        current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        self.current_bucket = {}

        bar_end_time = bucket_end.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._evaluate_entry()

    def _evaluate_entry(self):
        if self._has_option_holding() or self._entry_order_is_open():
            return

        if self.no_entry_today:
            return

        current_slice = self.CurrentSlice
        if current_slice is None or self.option_symbol not in current_slice.OptionChains:
            self.Debug(f"{self.Time}: Entry skipped; no option chain.")
            return

        option_chain = current_slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        call_contracts = [
            contract
            for contract in option_chain
            if contract.Right == OptionRight.Call
        ]

        expirations = sorted({
            contract.Expiry.date()
            for contract in call_contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug(f"{self.Time}: Entry skipped; no valid expiration.")
            return

        selected_expiry = expirations[0]
        spy_price = float(self.Securities[self.spy].Price)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in call_contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped; no qualifying call at "
                f"{selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if holding.Quantity <= 0:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()

        # Time stop on the trading day immediately preceding expiration.
        if (
            self.Time.time() >= time(15, 45)
            and current_trading_date_is_immediately_before(
                self.Time.date(), expiry_date
            )
        ):
            self._submit_exit("Expiration time stop")
            return

        if self.entry_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.entry_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _process_expiration_rules(self, current_date):
        if self.expiration_processed_date == current_date:
            return

        if self.entry_symbol is None:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.expiration_processed_date = current_date
            self.no_entry_today = True

            if self.Portfolio[self.entry_symbol].Quantity > 0:
                self._submit_exit("Expiration protection")

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"{self.Time}: Exit submitted; {reason}.")

    def _has_option_holding(self):
        return (
            self.entry_symbol is not None
            and self.Portfolio[self.entry_symbol].Quantity > 0
        )

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
