        self.Securities[self.spy].SetDataNormalizationMode(
            DataNormalizationMode.Raw
        )

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket = None
        self._bucket_values = None
        self._bucket_minute_ends = set()

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._no_entry_dates = set()

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_equity_position()
        self._process_expiration_and_time_stop(today, slice)

        if self._has_open_option_position():
            self._evaluate_profit_target(slice)

        if not self._entry_order_is_open() and not self._has_open_option_position():
            bar = slice.Bars.get(self.spy)
            if bar is not None:
                self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        end_time = minute_bar.EndTime
        local_time = end_time.time()
        session_start = 9 * 60 + 30
        session_end = 16 * 60

        minute_of_day = local_time.hour * 60 + local_time.minute

        if minute_of_day < session_start or minute_of_day > session_end:
            self._reset_bucket()
            return

        offset = minute_of_day - session_start
        bucket_end_minutes = (
            ((offset + 4) // 5) * 5 + session_start
        )

        bucket_end = end_time.replace(
            hour=bucket_end_minutes // 60,
            minute=bucket_end_minutes % 60,
            second=0,
            microsecond=0
        )

        if self._bucket != bucket_end:
            self._bucket = bucket_end
            self._bucket_values = {
                "open": minute_bar.Open,
                "high": minute_bar.High,
                "low": minute_bar.Low,
                "close": minute_bar.Close,
                "volume": minute_bar.Volume
            }
            self._bucket_minute_ends = {end_time}
        else:
            if end_time in self._bucket_minute_ends:
                return

            self._bucket_minute_ends.add(end_time)
            self._bucket_values["high"] = max(
                self._bucket_values["high"], minute_bar.High
            )
            self._bucket_values["low"] = min(
                self._bucket_values["low"], minute_bar.Low
            )
            self._bucket_values["close"] = minute_bar.Close
            self._bucket_values["volume"] += minute_bar.Volume

        # A complete five-minute bar ends at 09:35, 09:40, etc.
        if end_time != bucket_end:
            return

        # Missing minute data means the consolidated interval is invalid.
        if len(self._bucket_minute_ends) != 5:
            self._reset_bucket()
            return

        close = self._bucket_values["close"]
        bar_end = bucket_end
        previous_ready = self.fast.IsReady and self.slow.IsReady

        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        current_ready = self.fast.IsReady and self.slow.IsReady

        bullish_cross = (
            previous_ready
            and current_ready
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter(slice, close)

        self._reset_bucket()

    def _try_enter(self, slice: Slice, spy_price: float):
        current_date = self.Time.date()

        if current_date in self._no_entry_dates:
            return

        if self._entry_order_is_open() or self._has_open_option_position():
            return

        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped selection: no option chain")
            return

        minimum_expiry = current_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                if contract.Expiry.date() >= minimum_expiry:
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped selection: no expiration at least 7 days away")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in candidates
        )

        strike_floor = spy_price * 1.01
        contracts = [
            contract for contract in candidates
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= strike_floor
        ]

        if not contracts:
            self.Debug("Skipped selection: no qualifying call contract")
            return

        selected = min(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute SMA crossover"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry={selected.Expiry.date()} strike={selected.Strike}"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        if self._exit_order_is_open():
            return

        contract = None

        for chain in slice.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self._held_symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self._cancel_open_exit_orders()
            quantity = self.Portfolio[self._held_symbol].Quantity

            if quantity != 0:
                self._exit_ticket = self.MarketOrder(
                    self._held_symbol,
                    -quantity,
                    tag="50% profit target"
                )
                self.Debug(
                    f"Exit submitted: profit target midpoint={midpoint:.2f}"
                )

    def _process_expiration_and_time_stop(self, today, slice: Slice):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if not holding.Invested:
            return

        expiry = self._held_symbol.ID.Date.date()

        # Never intentionally carry an option into its expiration date.
        if today >= expiry:
            self._no_entry_dates.add(today)

            if not self._exit_order_is_open():
                quantity = holding.Quantity
                if quantity != 0:
                    self._exit_ticket = self.MarketOrder(
                        self._held_symbol,
                        -quantity,
                        tag="Expiration protection"
                    )
                    self.Debug("Exit submitted: expiration protection")
            return

        previous_trading_day = self._previous_trading_day(expiry)

        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
            and not self._exit_order_is_open()
        ):
            quantity = holding.Quantity
            if quantity != 0:
                self._exit_ticket = self.MarketOrder(
                    self._held_symbol,
                    -quantity,
                    tag="Expiration time stop"
                )
                self.Debug("Exit submitted: expiration time stop")

    def _previous_trading_day(self, expiry):
        candidate = expiry - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if not self.Transactions.GetOpenOrders(self.spy):
            self.Debug(
                f"Unexpected exercise or assignment: liquidating "
                f"{quantity} SPY shares"
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        order_id = order_event.OrderId

        if (
            self._entry_ticket is not None
            and order_id == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice:.2f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_id == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice:.2f}"
                )
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._exit_ticket = None

        event_text = str(order_event)
        if "Exercise" in event_text or "Assignment" in event_text:
            self.Debug(
                f"Unexpected exercise or assignment event: {event_text}"
            )

    def _has_open_option_position(self):
        return (
            self._held_symbol is not None
            and self.Portfolio[self._held_symbol].Invested
        )

    def _entry_order_is_open(self):
        return self._ticket_is_open(self._entry_ticket)

    def _exit_order_is_open(self):
        return self._ticket_is_open(self._exit_ticket)

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _cancel_open_exit_orders(self):
        if self._exit_order_is_open():
            self._exit_ticket.Cancel("Profit target reached")
            self._exit_ticket = None

    def _reset_bucket(self):
        self._bucket = None
        self._bucket_values = None
        self._bucket_minute_ends = set()
