        self.exit_tickets = []
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Immediately liquidate unexpected SPY equity positions.
        spy_holding = self.Portfolio[self.spy_symbol]
        if spy_holding.Invested:
            self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.blocked_entry_date = current_date
            self.Liquidate(self.spy_symbol, "Unexpected exercise or assignment")

        # Process expiration and minute-based exits.
        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.blocked_entry_date = current_date
                self._submit_exit("Expiration liquidation")
            elif (
                self.Time.time() >= time(15, 45)
                and current_date == self._previous_trading_day(expiry_date)
            ):
                self._submit_exit("Expiration time stop")
            else:
                self._check_profit_target(slice)

        # Consume the actual minute SPY bar and evaluate completed five-minute bars.
        if not slice.Bars.ContainsKey(self.spy_symbol):
            return

        minute_bar = slice.Bars[self.spy_symbol]
        completed_bar = self._consume_minute_bar(minute_bar)

        if completed_bar is not None:
            self._evaluate_crossover(slice, completed_bar)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.FillQuantity > 0:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"Entry filled: {self.held_symbol} at "
                        f"{self.entry_price:.4f}"
                    )

                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    if order_event.Status != OrderStatus.Filled:
                        self.entry_ticket = None

        for ticket in list(self.exit_tickets):
            if order_event.OrderId == ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    if order_event.Status == OrderStatus.Filled:
                        self.Debug(f"Exit filled: {order_event.Symbol}")
                        self.held_symbol = None
                        self.entry_price = None
                    self.exit_tickets.remove(ticket)

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment processed.")
            self.blocked_entry_date = self.Time.date()

    def _consume_minute_bar(self, bar):
        end_time = bar.EndTime
        local_time = end_time.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return None

        bucket_minute = ((end_time.minute + 4) // 5) * 5
        bucket_end = end_time.replace(
            minute=0, second=0, microsecond=0
        ) + timedelta(minutes=bucket_minute)

        if self.bucket_end is None:
            self.bucket_end = bucket_end

        completed = None

        if bucket_end != self.bucket_end:
            completed = self._finalize_bucket()
            self.bucket_bars = {}
            self.bucket_end = bucket_end

        self.bucket_bars[end_time] = bar
        return completed

    def _finalize_bucket(self):
        if self.bucket_end is None:
            return None

        expected_times = [
            self.bucket_end - timedelta(minutes=offset)
            for offset in range(1, 6)
        ]
        expected_times.reverse()

        if any(timestamp not in self.bucket_bars for timestamp in expected_times):
            return None

        bars = [self.bucket_bars[timestamp] for timestamp in expected_times]

        consolidated = TradeBar(
            self.bucket_end - timedelta(minutes=5),
            self.spy_symbol,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )
        return consolidated

    def _evaluate_crossover(self, slice, bar):
        self.closes.append(float(bar.Close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bar_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        if (
            bullish_crossover
            and eligible_time
            and self.blocked_entry_date != self.Time.date()
            and self.held_symbol is None
            and not self._entry_order_open()
        ):
            self._try_enter(slice, float(bar.Close))

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def _try_enter(self, slice, spy_price):
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible:
            self.Debug("Skipped entry: no eligible expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in eligible
        )

        strike_floor = spy_price * 1.01
        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover call entry"
        )

        self.Debug(f"Call entry submitted: {selected.Symbol}")

    def _check_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            return

        chain = slice.OptionChains[self.option_symbol]
        contract = next(
            (
                item for item in chain
                if item.Symbol == self.held_symbol
            ),
            None
        )

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        for ticket in list(self.exit_tickets):
            if self._ticket_is_open(ticket):
                ticket.Cancel("Replaced by liquidation order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_tickets.append(ticket)
        self.Debug(f"Exit submitted: {reason}")

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self._ticket_is_open(self.entry_ticket)
        )

    def _ticket_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date_value):
        candidate = datetime.combine(
            date_value - timedelta(days=1),
            time.min
        )

        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while candidate.weekday() >= 5 or not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()
