                and contract.Right == OptionRight.Call
                and float(contract.Strike) >= threshold
            )
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )[0]

        self.AddOptionContract(selected.Symbol, Resolution.Minute)

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId

        self.Debug("Entry submitted: " + str(selected.Symbol))

