from AlgorithmImports import *

from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)

        # Broad universe: weekly options, up to one year out, and a wide strike range.
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_start = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None

        self.time_stop_submitted = False
        self.target_submitted = False
        self.blocked_entry_date = None

    def OnData(self, data: Slice):
        today = self.Time.date()

        self._liquidate_unexpected_spy_position()
        self._process_expiration_safety(today)
        self._evaluate_open_position(data, today)
        self._process_minute_bar(data)

    def _process_minute_bar(self, data: Slice):
        if not data.Bars.ContainsKey(self.spy):
            return

        minute_bar = data.Bars[self.spy]
        local_start = minute_bar.Time

        if local_start.tzinfo is not None:
            local_start = local_start.replace(tzinfo=None)

        current_time = local_start.time()

        # Regular NYSE session only.
        if current_time < time(9, 30) or current_time >= time(16, 0):
            return

        bucket_minute = (local_start.minute // 5) * 5
        bucket_start = local_start.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if (
            self.current_bucket_start is not None
            and bucket_start != self.current_bucket_start
        ):
            self._complete_bucket()

        if self.current_bucket_start != bucket_start:
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = {}

        self.current_bucket_bars[local_start] = minute_bar

    def _complete_bucket(self):
        if self.current_bucket_start is None:
            return

        expected_times = [
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        # Missing minute data means the five-minute bar is discarded.
        if not all(t in self.current_bucket_bars for t in expected_times):
            self.current_bucket_start = None
            self.current_bucket_bars = {}
            return

        bars = [self.current_bucket_bars[t] for t in expected_times]

        consolidated = TradeBar(
            self.current_bucket_start,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self._on_five_minute_bar(consolidated)

        self.current_bucket_start = None
        self.current_bucket_bars = {}

    def _on_five_minute_bar(self, bar: TradeBar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if previous_fast is None or previous_slow is None:
            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = previous_fast
        self.previous_slow = previous_slow

        bar_end = bar.EndTime
        if bar_end.tzinfo is not None:
            bar_end = bar_end.replace(tzinfo=None)

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter_from_current_slice()

    def _try_enter_from_current_slice(self):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.held_contract is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        chain = self.CurrentSlice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        minimum_expiry = today + timedelta(days=7)

        contracts = []
        for contract in chain:
            if contract.Right != OptionRight.Call:
                continue
            if contract.Expiry.date() < minimum_expiry:
                continue
            contracts.append(contract)

        if not contracts:
            self.Debug("Skipped call selection: no expiration satisfies the rule.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price

        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not eligible:
            self.Debug(
                "Skipped call selection: no qualifying call at the selected expiration."
            )
            return

        selected = sorted(
            eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute SMA crossover"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={selected.Expiry.date()}, strike={selected.Strike}"
        )

    def _evaluate_open_position(self, data: Slice, today):
        if self.held_contract is None or self.entry_fill_price is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        current_time = self.Time.time()

        if (
            not self.time_stop_submitted
            and self.held_expiry is not None
            and today == self._previous_trading_day(self.held_expiry)
            and current_time >= time(15, 45)
        ):
            self._submit_exit("Expiration time stop")
            return

        if self.target_submitted:
            return

        midpoint = self._get_current_midpoint(data, self.held_contract)
        if midpoint is None:
            return

        if midpoint >= 1.50 * self.entry_fill_price:
            self._submit_exit("50% profit target")

    def _get_current_midpoint(self, data: Slice, symbol):
        if data.QuoteBars.ContainsKey(symbol):
            quote = data.QuoteBars[symbol]

            if quote.Bid is not None and quote.Ask is not None:
                bid = quote.Bid.Close
                ask = quote.Ask.Close

                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

        chain = data.OptionChains.get(self.option.Symbol)
        if chain is not None:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue

                bid = contract.BidPrice
                ask = contract.AskPrice

                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

        return None

    def _submit_exit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.Transactions.CancelOrder(
                self.exit_ticket.OrderId,
                "Replacing open exit order"
            )

        self.exit_ticket = self.MarketOrder(
            self.held_contract,
            -quantity,
            tag=reason
        )

        if reason == "50% profit target":
            self.target_submitted = True
        else:
            self.time_stop_submitted = True

        self.Debug(f"Exit submitted: {self.held_contract}, reason={reason}")

    def _process_expiration_safety(self, today):
        if self.held_contract is None or self.held_expiry is None:
            return

        if today >= self.held_expiry:
            self.blocked_entry_date = today

            quantity = self.Portfolio[self.held_contract].Quantity
            if quantity > 0:
                self._submit_exit("Expiration safety liquidation")

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position detected: quantity={quantity}. "
                "Liquidating immediately."
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment handling"
            )

    def _previous_trading_day(self, calendar_date):
        previous = calendar_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(previous):
            previous -= timedelta(days=1)

        return previous

    def _ticket_is_open(self, ticket):
        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.Debug(
                    f"Entry filled: {self.held_contract}, "
                    f"fill={self.entry_fill_price}"
                )

            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol}")

            if self.held_contract == order_event.Symbol:
                self.held_contract = None
                self.held_expiry = None
                self.entry_fill_price = None
                self.exit_ticket = None
                self.time_stop_submitted = False
                self.target_submitted = False
