from AlgorithmImports import *
from datetime import timedelta, time


class SpyBullishCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

        self.minute_buckets = {}

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def OnData(self, slice: Slice):
        self.current_slice = slice

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is not None:
            self._record_minute(spy_bar)

        self._process_expiration_and_time_stop()
        self._process_profit_target()

    def _record_minute(self, bar: TradeBar):
        minute_time = bar.Time
        if not (time(9, 30) <= minute_time.time() < time(16, 0)):
            return

        bucket_start = minute_time.replace(
            minute=(minute_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        self.minute_buckets.setdefault(bucket_start, set()).add(minute_time)

        cutoff = bucket_start - timedelta(minutes=30)
        self.minute_buckets = {
            key: value
            for key, value in self.minute_buckets.items()
            if key >= cutoff
        }

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        end_time = bar.EndTime
        if not (time(9, 35) <= end_time.time() <= time(16, 0)):
            return

        bucket_start = end_time - timedelta(minutes=5)
        observed = self.minute_buckets.get(bucket_start, set())

        expected = {
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        }

        if observed != expected:
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_crossover:
            eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)
            if eligible_time:
                self._try_enter()

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def _try_enter(self):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.entry_ticket is not None:
            return

        if self.held_symbol is not None:
            holding = self.Portfolio[self.held_symbol]
            if holding.Invested:
                return

        if self.current_slice is None:
            self.Debug("Skipped entry: no current Slice.")
            return

        chains = list(self.current_slice.OptionChains)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)

        candidates = []
        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    candidates.append((expiry_date, contract))

        if not candidates:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = min(expiry for expiry, _ in candidates)

        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        strike_floor = 1.01 * spy_price

        contracts = [
            contract
            for expiry, contract in candidates
            if expiry == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= strike_floor
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        contracts.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = contracts[0]

        quantity = 1
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            quantity,
            tag="Bullish SPY call entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={selected.Expiry.date()}, strike={selected.Strike}"
        )

    def _process_profit_target(self):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None:
            return

        contract = self._find_current_contract(self.held_symbol)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration_and_time_stop(self):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.no_entry_date = today
            self._submit_exit("expiration protection")
            return

        preceding_trading_day = self._preceding_trading_day(expiry_date)

        if (
            today == preceding_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(
                self.exit_ticket.OrderId,
                "Replacing open exit order"
            )

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol}, reason={reason}")

