from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.close_history = []

        self.bucket_end = None
        self.bucket_closes = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._process_option_exits(slice)

        bar = None
        if slice.Bars.ContainsKey(self.spy):
            bar = slice.Bars[self.spy]

        if bar is None:
            return

        end_time = bar.EndTime
        if not self._is_regular_session_time(end_time):
            return

        current_bucket = self._bucket_end(end_time)

        if self.bucket_end is not None and current_bucket != self.bucket_end:
            # The prior interval did not produce a complete boundary bar.
            self.bucket_end = None
            self.bucket_closes = []

        if self.bucket_end is None:
            self.bucket_end = current_bucket
            self.bucket_closes = []

        self.bucket_closes.append(bar.Close)

        if end_time >= self.bucket_end:
            close_time = self.bucket_end
            close_price = self.bucket_closes[-1]

            self.bucket_end = None
            self.bucket_closes = []

            self._process_five_minute_bar(close_time, close_price, slice)

    def _process_five_minute_bar(self, close_time, close_price, slice):
        self.close_history.append(float(close_price))
        if len(self.close_history) > self.slow_period + 1:
            self.close_history.pop(0)

        if len(self.close_history) < self.slow_period + 1:
            return

        previous_fast = sum(self.close_history[-self.fast_period - 1:-1]) / self.fast_period
        previous_slow = sum(self.close_history[-self.slow_period - 1:-1]) / self.slow_period
        current_fast = sum(self.close_history[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.close_history[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if not bullish_cross:
            return

        if not (time(9, 45) <= close_time.time() <= time(14, 30)):
            return

        self._try_enter(slice, close_price)

    def _try_enter(self, slice, spy_price):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        try:
            chain = slice.OptionChains.get(self.option_symbol)
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = list(chain)

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no qualifying expiration")
            return

        selected_expiry = expiries[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        candidates.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))

        contract = candidates[0]
        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)

        self.Debug(
            "Entry submitted: {} expiry {} strike {}".format(
                contract.Symbol,
                selected_expiry,
                contract.Strike
            )
        )

    def _process_option_exits(self, slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        expiry_date = self.held_option.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.no_entry_date = today
            self._submit_exit("expiration protection")
            return

        stop_date = self._previous_trading_day(expiry_date)

        if today == stop_date and self.Time.time() >= time(15, 45):
            self._submit_exit("time stop")
            return

        try:
            chain = slice.OptionChains.get(self.option_symbol)
        except Exception:
            chain = None

        if chain is None:
            return

        contract = None
        for item in chain:
            if item.Symbol == self.held_option:
                contract = item
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            if reason == "50% profit target":
                self.exit_ticket.Cancel("Profit target superseded prior exit")
            else:
                return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity
        )

        self.Debug(
            "Exit submitted: {} ({})".format(
                self.held_option,
                reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_option,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {}".format(order_event.Symbol))
            self.exit_ticket = None
            self.held_option = None
            self.entry_price = None

        if order_event.OrderType == OrderType.OptionExercise:
            self.no_entry_date = self.Time.date()
            self.Debug(
                "Unexpected exercise or assignment: {}".format(
                    order_event.Symbol
                )
            )
            self._liquidate_spy_position()

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected SPY equity position; liquidating")
            self._liquidate_spy_position()

    def _liquidate_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)

        candidate_datetime = datetime(
            candidate.year,
            candidate.month,
            candidate.day
        )

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            candidate_datetime
        ):
            candidate -= timedelta(days=1)
            candidate_datetime = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )

        return candidate

    @staticmethod
    def _is_regular_session_time(value):
        session_start = time(9, 30)
        session_end = time(16, 0)
        return session_start < value.time() <= session_end

    @staticmethod
    def _bucket_end(value):
        minutes_since_open = (
            value.hour * 60 + value.minute
        ) - (9 * 60 + 30)

        bucket_minutes = (
            ((minutes_since_open + 4) // 5) * 5
        ) + (9 * 60 + 30)

        return value.replace(
            hour=bucket_minutes // 60,
            minute=bucket_minutes % 60,
            second=0,
            microsecond=0
        )

    @staticmethod
    def _order_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )
