        expiry_date = self.held_option.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.no_entry_date = today
            self._submit_exit("expiration protection")
            return

        stop_date = self._previous_trading_day(expiry_date)

        if today == stop_date and self.Time.time() >= time(15, 45):
            self._submit_exit("time stop")
            return

        try:
            chain = slice.OptionChains.get(self.option_symbol)
        except Exception:
            chain = None

        if chain is None:
            return

        contract = None
        for item in chain:
            if item.Symbol == self.held_option:
                contract = item
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

