            order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {}".format(order_event.Symbol))
            self.exit_ticket = None
            self.held_option = None
            self.entry_price = None

        if order_event.OrderType == OrderType.OptionExercise:
            self.no_entry_date = self.Time.date()
            self.Debug(
                "Unexpected exercise or assignment: {}".format(
                    order_event.Symbol
                )
            )
            self._liquidate_spy_position()

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected SPY equity position; liquidating")
            self._liquidate_spy_position()

    def _liquidate_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)

        candidate_datetime = datetime(
            candidate.year,
            candidate.month,
            candidate.day
        )

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            candidate_datetime
        ):
            candidate -= timedelta(days=1)
            candidate_datetime = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )

        return candidate

    @staticmethod
    def _is_regular_session_time(value):
        session_start = time(9, 30)
        session_end = time(16, 0)
        return session_start < value.time() <= session_end

    @staticmethod
    def _bucket_end(value):
        minutes_since_open = (
            value.hour * 60 + value.minute
        ) - (9 * 60 + 30)

        bucket_minutes = (
            ((minutes_since_open + 4) // 5) * 5
        ) + (9 * 60 + 30)

        return value.replace(
            hour=bucket_minutes // 60,
            minute=bucket_minutes % 60,
            second=0,
            microsecond=0
        )

    @staticmethod
    def _order_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

