        end = bar.EndTime.replace(second=0, microsecond=0)
        date = end.date()

        if self.current_bar_date != date:
            self.minute_bars.clear()
            self.current_bar_date = date

        # Only regular-session minute bars are used.
        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return None

        self.minute_bars[end] = bar

        # A five-minute bar ends on a New York clock boundary.
        if end.minute % 5 != 0:
            return None

        expected_times = [
            end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(t not in self.minute_bars for t in expected_times):
            # Do not synthesize or forward-fill a missing five-minute bar.
            for t in list(self.minute_bars):
                if t <= end:
                    del self.minute_bars[t]
            return None

        bars = [self.minute_bars[t] for t in expected_times]

        for t in list(self.minute_bars):
            if t <= end:
                del self.minute_bars[t]

        return {
            "end": end,
            "close": bars[-1].Close
        }

    def _try_enter(self, data, spy_price):
        chain = None

        try:
            chain = data.OptionChains[self.option.Symbol]
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        eligible = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration satisfies the rule.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in eligible
        )

        strike_floor = 1.01 * spy_price
        candidates = [
            contract
            for contract in eligible
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call strike is at least 1% out of the money."
            )
            return

        selected = min(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.held_symbol = selected.Symbol
        self.entry_fill_quantity = 0
        self.entry_fill_value = 0.0
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}"
        )

    def _get_current_midpoint(self, data, symbol):
        try:
            chain = data.OptionChains[self.option.Symbol]
        except Exception:
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                bid = contract.BidPrice
                ask = contract.AskPrice

                if bid is not None and ask is not None and bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

        return None

    def _get_held_expiry(self):
        if self.held_symbol is None:
            return None

        try:
            return self.Securities[self.held_symbol].Symbol.ID.Date.date()
        except Exception:
            return None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._ticket_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Canceling entry before exit.")

        if self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing existing exit order.")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {self.held_symbol} ({reason})")

    def _clear_finished_tickets(self):
        if (
            self.entry_ticket is not None
            and not self._ticket_is_open(self.entry_ticket)
            and self.Portfolio[self.entry_ticket.Symbol].Quantity == 0
        ):
            if self.entry_ticket.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.entry_ticket = None
                self.held_symbol = None

        if (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            )
        ):
            self.exit_ticket = None

    @staticmethod
    def _ticket_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )
