                    completed
                )

        if signal and self._eligible_entry_time(signal_end):
            self._try_enter(slice, signal_price)

    def _accumulate_minute_bar(self, bar):
        local_end = bar.EndTime
        local_start = local_end - timedelta(minutes=1)
        session_start = local_start.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        session_end = local_start.replace(
            hour=16, minute=0, second=0, microsecond=0
        )

        if local_start < session_start or local_start >= session_end:
            return None

        minutes_from_open = int((local_start - session_start).total_seconds() / 60)
        bucket_end = session_start + timedelta(
            minutes=((minutes_from_open // 5) + 1) * 5
        )

        completed = None

        if (
            self.current_bucket_end is not None
            and bucket_end != self.current_bucket_end
        ):
            completed = self._finalize_bucket(self.current_bucket_end)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[local_start] = bar
        return completed

    def _finalize_bucket(self, bucket_end):
        expected_starts = [
            bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        if any(start not in self.bucket_bars for start in expected_starts):
            self.bucket_bars = {}
            return None

        bars = [self.bucket_bars[start] for start in expected_starts]
        close = bars[-1].Close
        self.bucket_bars = {}

