            return

        holding = self.Portfolio[symbol]
        if not holding.Invested or self.entry_price is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
