            Market.USA,
            False,
            1,
            False
        )
        self.spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = self.spy_security.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(lambda u: u.Strikes(-100, 100).Expiration(0, 365))
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.entry_signal_time = None
        self.blocked_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        local_end = self.TimeInNewYork(bar.EndTime)

        if local_end.time() < time(9, 35) or local_end.time() > time(16, 0):
            return

        if local_end.weekday() >= 5:
            return

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = float(self.fast.Current.Value) if previous_ready else None
        previous_slow = float(self.slow.Current.Value) if previous_ready else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        eligible_time = time(9, 45) <= local_end.time() <= time(14, 30)
        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if (
            eligible_time
            and bullish_cross
            and self.held_symbol is None
            and not self.IsEntryOrderOpen()
        ):
            self.entry_signal_time = bar.EndTime

    def OnData(self, slice: Slice):
        today = self.TimeInNewYork(self.Time).date()

        self.HandleUnexpectedSpyPosition(today)

        if self.held_symbol is not None:
            self.ManageOpenOption(slice, today)

        if (
            self.entry_signal_time is not None
            and self.held_symbol is None
            and not self.IsEntryOrderOpen()
            and self.blocked_entry_date != today
        ):
            signal_time = self.entry_signal_time
            self.entry_signal_time = None
            self.TryEnterFromCurrentSlice(slice, signal_time)

    def TryEnterFromCurrentSlice(self, slice: Slice, signal_time: datetime):
        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: current Slice has no option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        algorithm_date = self.TimeInNewYork(self.Time).date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts = list(chain)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        spy_price = float(self.Securities[self.spy].Price)

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        if self.entry_ticket is not None:
            self.Debug(
                "Entry submitted: {} expiry={} strike={}".format(
                    selected.Symbol,
                    selected_expiry,
                    selected.Strike
                )
            )

    def ManageOpenOption(self, slice: Slice, today):
        symbol = self.held_symbol
        security = self.Securities[symbol]

        expiry_date = security.Symbol.ID.Date.date()

        if today >= expiry_date:
            self.blocked_entry_date = today
            self.SubmitOptionLiquidation("expiration processing")
            return

        previous_trading_day = self.PreviousTradingDay(expiry_date)

        current_local_time = self.TimeInNewYork(self.Time).time()
        if (
            today == previous_trading_day
            and current_local_time >= time(15, 45)
        ):
            self.SubmitOptionLiquidation("expiration time stop")
            return

        if self.entry_price is None or symbol not in slice.OptionChains:
            return

        bid = None
        ask = None

        for contract in slice.OptionChains[symbol.Canonical]:
            if contract.Symbol == symbol:
                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)
                break

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitOptionLiquidation("50% profit target")

    def SubmitOptionLiquidation(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_symbol, reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected exercise or assignment detected.")
            self.blocked_entry_date = self.TimeInNewYork(self.Time).date()
            self.HandleUnexpectedSpyPosition(self.blocked_entry_date)

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        "Entry filled: {} at {}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )
                    self.entry_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: {}".format(order_event.Symbol))
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def HandleUnexpectedSpyPosition(self, today):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.MarketOrder(self.spy, -quantity)
            self.blocked_entry_date = today

    def IsEntryOrderOpen(self):
        return (
            self.entry_ticket is not None
            and self.IsOrderOpen(self.entry_ticket)
        )

    def IsOrderOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def PreviousTradingDay(self, date_value):
        date_value -= timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while date_value.weekday() >= 5 or not hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    def TimeInNewYork(self, value):
        return Extensions.ConvertTo(
            value,
            self.TimeZone,
            DateTimeZoneProviders.Tzdb["America/New_York"]
        )
