from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone("America/New_York")

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        )

        self.spy_option = self.add_option("SPY", Resolution.MINUTE)
        self.spy_option.set_filter(
            lambda universe: universe
                .include_weeklys()
                .strikes(-1000, 1000)
                .expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_start = None
        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

    def on_data(self, slice: Slice):
        current_date = self.time.date()

        # Unexpected delivered SPY shares from exercise or assignment.
        spy_quantity = self.portfolio[self.spy.symbol].quantity
        if spy_quantity != 0:
            self.debug(
                f"Unexpected SPY position from exercise/assignment; "
                f"liquidating {spy_quantity} shares"
            )
            self.market_order(self.spy.symbol, -spy_quantity)
            self.no_entry_date = current_date

        spy_bar = slice.bars.get(self.spy.symbol)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

        if self.held_option is not None:
            expiry_date = self.held_option.id.date.date()

            # Never intentionally hold through expiration.
            if current_date >= expiry_date:
                self.debug(
                    f"Expiration liquidation for {self.held_option} "
                    f"on {current_date}"
                )
                self.no_entry_date = current_date
                self._submit_exit("expiration")
                return

            # Time stop at 15:45 on the immediately preceding trading day.
            if (
                self.time.hour == 15
                and self.time.minute == 45
                and self._is_immediately_preceding_trading_day(
                    current_date, expiry_date
                )
            ):
                self.debug(f"Time-stop exit for {self.held_option}")
                self._submit_exit("time stop")
                return

            # Profit target uses only a strictly positive current midpoint.
            quote = slice.quote_bars.get(self.held_option)
            if quote is not None and quote.bid is not None and quote.ask is not None:
                bid = quote.bid.close
                ask = quote.ask.close

                if bid > 0 and ask > 0 and self.entry_price is not None:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= 1.50 * self.entry_price:
                        self.debug(
                            f"Profit target reached for {self.held_option}; "
                            f"midpoint={midpoint:.4f}"
                        )
                        self._submit_exit("profit target")

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        start = bar.time
        session_start = datetime(
            start.year, start.month, start.day, 9, 30
        )
        session_end = datetime(
            start.year, start.month, start.day, 16, 0
        )

        if start < session_start or start >= session_end:
            return

        minutes_from_open = int((start - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=5 * (minutes_from_open // 5)
        )
        bucket_end = bucket_start + timedelta(minutes=5)

        if self.bucket_end != bucket_end:
            self._flush_bucket(slice)
            self.bucket_start = bucket_start
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[start] = bar

        # The five-minute bar closes when the 09:34 minute bar arrives.
        expected_final_minute = bucket_end - timedelta(minutes=1)
        if expected_final_minute in self.bucket_bars:
            self._flush_bucket(slice)
            self.bucket_start = None
            self.bucket_end = None
            self.bucket_bars = {}

    def _flush_bucket(self, slice: Slice):
        if self.bucket_start is None or self.bucket_end is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        # Missing minutes invalidate the entire consolidated interval.
        if not all(t in self.bucket_bars for t in expected_times):
            return

        closes = [self.bucket_bars[t].close for t in expected_times]
        consolidated_close = closes[-1]
        end_time = self.bucket_end

        previous_fast = self.fast.current.value if self.fast.is_ready else None
        previous_slow = self.slow.current.value if self.slow.is_ready else None

        self.fast.update(IndicatorDataPoint(end_time, consolidated_close))
        self.slow.update(IndicatorDataPoint(end_time, consolidated_close))

        if not self.fast.is_ready or not self.slow.is_ready:
            return

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and self.fast.current.value > self.slow.current.value
        )

        if not bullish_crossover:
            return

        end_clock = end_time.time()
        if not (
            datetime.strptime("09:45", "%H:%M").time()
            <= end_clock
            <= datetime.strptime("14:30", "%H:%M").time()
        ):
            return

        self._try_enter(slice, consolidated_close)

    def _try_enter(self, slice: Slice, spy_price: float):
        current_date = self.time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.status.is_closed():
            return

        if spy_price <= 0:
            self.debug("Skipped entry: invalid SPY price")
            return

        try:
            chain = slice.option_chains.get(self.spy_option.symbol)
        except Exception:
            chain = None

        if chain is None:
            self.debug("Skipped entry: no option chain")
            return

        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.debug("Skipped entry: no expiration at least seven days out")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.expiry.date() == selected_expiry
            and contract.right == OptionRight.CALL
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug(
                f"Skipped entry: no qualifying call for {selected_expiry}"
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.strike, str(contract.symbol))
        )

        self.entry_ticket = self.market_order(
            selected.symbol,
            1,
            tag="bullish SPY crossover entry"
        )

        self.debug(
            f"Call entry submitted: {selected.symbol}, "
            f"strike={selected.strike}, expiry={selected_expiry}"
        )

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.portfolio[self.held_option].quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self.exit_ticket.status.is_closed():
            self.exit_ticket.cancel("replaced by liquidation order")

        self.exit_ticket = self.market_order(
            self.held_option,
            -quantity,
            tag=f"SPY call {reason}"
        )

