                if contract.Expiry.date() == nearest_expiration
            ),
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_price = None
        self.held_option = selected.Symbol

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry={nearest_expiration} strike={selected.Strike}"
        )

    def EvaluateProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.IsExitOrderOpen():
            return

        contract = None

        for chain in slice.OptionChains.Values:
            candidate = chain.Contracts.get(self.held_option)
            if candidate is not None:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.CancelOpenExitOrder()

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=f"Option exit: {reason}"
        )
        self.Debug(f"Exit submitted: {reason}")

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0 and not self.equity_liquidation_submitted:
            self.Debug("Unexpected SPY equity position; liquidating immediately")
            self.equity_liquidation_submitted = True
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def HasOptionHolding(self):
        return (
            self.held_option is not None
            and self.Portfolio[self.held_option].Quantity != 0
        )

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def CancelOpenExitOrder(self):
        if self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Superseded by another exit")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            ):
                if self.entry_price is None:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"Entry filled: {self.held_option} "
                        f"price={self.entry_price}"
                    )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order canceled or invalid")
                self.entry_ticket = None
                self.entry_price = None
                self.held_option = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Option exit filled")
            self.exit_ticket = None
            self.entry_ticket = None
            self.entry_price = None
            self.held_option = None
