from AlgorithmImports import *
from datetime import timedelta
from collections import deque


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        spy = self.AddEquity("SPY", Resolution.Minute)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None
        self.assignment_exit_order_id = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()
        self._process_expiration()
        self._evaluate_position_exit(slice)

        if self.spy_symbol not in slice.Bars:
            return

        bar = slice.Bars[self.spy_symbol]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        local_date = end_time.date()
        local_time = end_time.time()

        if local_time < time(9, 30) or local_time > time(16, 0):
            return

        session_start = datetime(
            local_date.year, local_date.month, local_date.day, 9, 35
        )

        minutes_from_first_close = int(
            (end_time - session_start).total_seconds() // 60
        )
        bucket_end = session_start + timedelta(
            minutes=(minutes_from_first_close // 5) * 5
        )

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        if end_time != self.bucket_end:
            return

        expected_times = {
            self.bucket_end - timedelta(minutes=i)
            for i in range(5)
        }

        actual_times = {item.EndTime for item in self.bucket_bars}

        if len(self.bucket_bars) != 5 or actual_times != expected_times:
            self.bucket_bars = []
            return

        consolidated = TradeBar(
            self.bucket_bars[0].Time,
            self.spy_symbol,
            self.bucket_bars[0].Open,
            max(item.High for item in self.bucket_bars),
            min(item.Low for item in self.bucket_bars),
            self.bucket_bars[-1].Close,
            sum(item.Volume for item in self.bucket_bars),
            timedelta(minutes=5)
        )

        self.bucket_bars = []
        self._process_five_minute_bar(consolidated, slice)

    def _process_five_minute_bar(self, bar: TradeBar, slice: Slice):
        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter(slice, float(bar.Close))

    def _try_enter(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_symbol is not None:
            return

        if self._is_order_open(self.entry_ticket):
            return

        if self.Portfolio[self.spy_symbol].Quantity != 0:
            return

        chains = self._get_option_chains(slice)

        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)
        expiries = set()

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    expiries.add(expiry_date)

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 days away.")
            return

        selected_expiry = min(expiries)
        minimum_strike = 1.01 * spy_price
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                if (
                    contract.Expiry.date() == selected_expiry
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry={selected_expiry} strike={selected.Strike}"
        )

    def _evaluate_position_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.no_entry_date = today
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self._is_order_open(self.exit_ticket):
            return

        contract = self._find_contract(slice, self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self._is_order_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.entry_ticket is not None and self._is_order_open(self.entry_ticket):
            self.entry_ticket.Cancel("Exit requested before entry completed")

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(f"Exit submitted: {self.held_symbol} reason={reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)

            self.Debug(
                f"Entry filled: {self.held_symbol} "
                f"price={self.entry_price}"
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol}")

            if self.held_symbol == order_event.Symbol:
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self._handle_unexpected_assignment()

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentOrderEvent):
        self._handle_unexpected_assignment()

    def _handle_unexpected_assignment(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity

        self.Debug(
            f"Unexpected exercise or assignment handling: "
            f"SPY quantity={quantity}"
        )

        self.no_entry_date = self.Time.date()

        if quantity != 0 and self.assignment_exit_order_id is None:
            ticket = self.MarketOrder(self.spy_symbol, -quantity)
            self.assignment_exit_order_id = ticket.OrderId

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity

        if quantity != 0 and self.held_symbol is not None:
            self._handle_unexpected_assignment()

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            self._submit_exit("expiration processing")

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours
        date_time = datetime(
            date_value.year, date_value.month, date_value.day
        )

        try:
            return exchange_hours.GetPreviousTradingDay(date_time).date()
        except Exception:
            candidate = date_value - timedelta(days=1)
            while candidate.weekday() >= 5:
                candidate -= timedelta(days=1)
            return candidate

    def _get_option_chains(self, slice: Slice):
        try:
            return list(slice.OptionChains.Values)
        except Exception:
            chains = []
            try:
                for key in slice.OptionChains:
                    chains.append(slice.OptionChains[key])
            except Exception:
                pass
            return chains

    def _find_contract(self, slice: Slice, symbol: Symbol):
        for chain in self._get_option_chains(slice):
            try:
                contract = chain.Contracts[symbol]
                if contract is not None:
                    return contract
            except Exception:
                pass

        return None

    def _is_order_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in {
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        }
