    def _has_open_exit_order(self):
        return (
            self._exit_ticket is not None
            and self._exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            )
        )

    def _get_option_chain(self, slice: Slice):
        for chain in slice.OptionChains:
            if chain.Symbol == self.option.Symbol:
                return chain
        return None

    def _get_current_contract(self, slice: Slice, symbol):
        chain = self._get_option_chain(slice)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                return contract
        return None

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    @staticmethod
    def _time(hour, minute):
        return timedelta(hours=hour, minutes=minute).seconds
