        self.spy_cleanup_ticket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Handle unexpected exercise or assignment.
        spy_holding = self.Portfolio[self.spy]
        if (
            spy_holding.Quantity != 0
            and not self._ticket_is_open(self.spy_cleanup_ticket)
        ):
            self.Debug("Unexpected exercise/assignment; liquidating SPY equity")
            self.spy_cleanup_ticket = self.MarketOrder(
                self.spy,
                -spy_holding.Quantity,
                tag="exercise/assignment cleanup"
            )

        # Never intentionally hold through expiration.
        if self.held_option is not None:
            expiry = self.held_option.ID.Date.date()

            if today >= expiry:
                self.expiration_block_date = today
                self._submit_exit("expiration-day protection")

        # Minute-based exit processing.
        if (
            self.held_option is not None
            and today != self.expiration_block_date
        ):
            self._check_minute_exit(slice)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        # Minute bars are aligned to New York clock boundaries.
        bar_time = bar.Time
        if bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if start.time() < time(9, 30) or start.time() >= time(16, 0):
            return

        if self.bucket_start is None:
            self.bucket_start = start

        elif start != self.bucket_start:
            self._finish_bucket(slice)
            self.bucket_bars = []
            self.bucket_start = start

        self.bucket_bars.append(bar)

    def _finish_bucket(self, slice: Slice):
        # Do not synthesize incomplete five-minute bars.
        if len(self.bucket_bars) != 5:
            return

        close = self.bucket_bars[-1].Close
        self.closes.append(close)

        if len(self.closes) < 21:
            return

        previous_fast = sum(self.closes[-6:-1]) / 5.0
        previous_slow = sum(self.closes[-21:-1]) / 20.0
        current_fast = sum(self.closes[-5:]) / 5.0
        current_slow = sum(self.closes[-20:]) / 20.0

        bar_end = self.bucket_start + timedelta(minutes=5)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_cross and eligible_time:
            self._try_entry(slice)

