        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no qualifying expiration")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_bar.Close

        candidates = [
            contract
            for contract in chain
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover"
        )

        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _check_minute_exit(self, slice: Slice):
        chain = slice.OptionChains.get(self.option.Symbol)
        contract = None

        if chain is not None:
            contract = next(
                (c for c in chain if c.Symbol == self.held_option),
                None
            )

        # Profit target requires strictly positive bid and ask.
        if (
            contract is not None
            and contract.BidPrice > 0
            and contract.AskPrice > 0
            and self.entry_price is not None
        ):
            midpoint = (contract.BidPrice + contract.AskPrice) / 2.0

            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("50% profit target")

        expiry = self.held_option.ID.Date.date()
        expiry_datetime = datetime(
            expiry.year,
            expiry.month,
            expiry.day
        )

        previous_trading_day = (
            self.Securities[self.spy]
            .Exchange
            .Hours
            .GetPreviousTradingDay(expiry_datetime)
            .date()
        )

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
