    def _check_profit_target(self, slice: Slice):
        if (
            self.held_symbol is None
            or self.entry_price is None
            or self.exit_ticket is not None
        ):
            return

        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(self.held_symbol)

            if contract is None:
                continue

            if contract.BidPrice > 0 and contract.AskPrice > 0:
                midpoint = (contract.BidPrice + contract.AskPrice) / 2.0

                if midpoint >= 1.5 * self.entry_price:
                    self._cancel_open_exit()
                    self._submit_exit("50% midpoint profit target")

            return

