            getattr(order_event, "IsAssignment", False)
            or getattr(order_event, "IsExercise", False)
        ):
            self.Debug("Unexpected exercise or assignment detected")
            self._liquidate_unexpected_spy()

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option assignment detected")
        self._liquidate_unexpected_spy()

    def _liquidate_unexpected_spy(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug("Liquidating unexpected SPY equity position")
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="unexpected exercise or assignment"
            )

