        current = dt.time()
        return time(9, 31) <= current <= time(16, 0)

    def _is_regular_five_minute_end(self, dt):
        current = dt.time()
        return (
            time(9, 35) <= current <= time(16, 0)
            and current.minute % 5 == 0
        )

    def _eligible_entry_time(self, signal_end):
        current = signal_end.time()
        return time(9, 45) <= current <= time(14, 30)

    def _is_expiration_eve(self, now, expiry_date):
        if now.time() < time(15, 45):
            return False

        candidate = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return now.date() == candidate

