        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {self.held_symbol}, reason={reason}")

    def ProcessExpiration(self):
        self.ProcessExpirationIfNeeded(self.Time.date())

    def ProcessExpirationIfNeeded(self, today):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if today >= expiry:
            self.blocked_entry_date = today
            self.SubmitExit("Expiration processing protection")

    def IsTradingDayImmediatelyBeforeExpiry(self, current_date, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while candidate > current_date:
            candidate -= timedelta(days=1)

        return (
            candidate == current_date
            and self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                self.Time.replace(
                    year=candidate.year,
                    month=candidate.month,
                    day=candidate.day,
                    hour=0,
                    minute=0,
                    second=0
                )
            )
        )

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            if not self.assignment_liquidation_submitted:
                self.assignment_liquidation_submitted = True
                self.Debug(
                    f"Unexpected SPY equity position detected, quantity={quantity}; "
                    "liquidating immediately."
                )
                self.MarketOrder(
                    self.spy,
                    -quantity,
                    tag="Unexpected exercise or assignment liquidation"
                )
        else:
            self.assignment_liquidation_submitted = False

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            f"Unexpected exercise or assignment event received: "
            f"{assignment_event}"
        )
        self.blocked_entry_date = self.Time.date()
        self.HandleUnexpectedEquityPosition()

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.time_stop_submitted = False

                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"fill price={self.entry_price}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
