from datetime import datetime, timedelta, time

from AlgorithmImports import *


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)

        self.current_bucket_end = None
        self.current_bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.no_entry_date = None
        self.expiration_processing_date = None
        self.spy_liquidation_submitted = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_expiration_processing()
        self._evaluate_option_exit(slice)
        self._handle_unexpected_spy_position()

        bar = None
        if slice.Bars.ContainsKey(self.spy):
            bar = slice.Bars[self.spy]

        if bar is not None:
            self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        end_time = minute_bar.EndTime
        current_date = self.Time.date()

        if end_time.date() != current_date:
            return

        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return

        bucket_minute = ((end_time.minute + 4) // 5) * 5
        bucket_end = end_time.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=bucket_minute)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.current_bucket_bars = []

        expected_start = bucket_end - timedelta(minutes=4)
        expected_end = expected_start + timedelta(
            minutes=len(self.current_bucket_bars)
        )

        if end_time != expected_end:
            self.current_bucket_bars = []
            expected_start = bucket_end - timedelta(minutes=4)
            expected_end = expected_start

        if end_time == expected_end:
            self.current_bucket_bars.append(minute_bar)

        if end_time != bucket_end:
            return

        completed_bars = self.current_bucket_bars
        self.current_bucket_bars = []

        if len(completed_bars) != 5:
            self.Debug(
                f"Skipped incomplete five-minute SPY bar ending {bucket_end}"
            )
            return

        consolidated = TradeBar(
            bucket_end - timedelta(minutes=5),
            self.spy,
            completed_bars[0].Open,
            max(bar.High for bar in completed_bars),
            min(bar.Low for bar in completed_bars),
            completed_bars[-1].Close,
            sum(bar.Volume for bar in completed_bars),
            timedelta(minutes=5)
        )

        self._process_five_minute_bar(consolidated, slice)

    def _process_five_minute_bar(self, bar: TradeBar, slice: Slice):
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        fast = sum(
            self.closes[i] for i in range(self.fast_period)
        ) / self.fast_period

        slow = sum(
            self.closes[i] for i in range(self.slow_period)
        ) / self.slow_period

        previous_fast = None
        previous_slow = None

        if self.closes.Count >= self.slow_period + 1:
            previous_fast = sum(
                self.closes[i] for i in range(1, self.fast_period + 1)
            ) / self.fast_period

            previous_slow = sum(
                self.closes[i] for i in range(1, self.slow_period + 1)
            ) / self.slow_period

        bar_end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        bullish_crossover = (
            previous_fast is not None
            and previous_fast <= previous_slow
            and fast > slow
        )

        if not eligible_time or not bullish_crossover:
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self._ticket_finished(
            self.entry_ticket
        ):
            return

        self._submit_entry(slice, float(bar.Close))

    def _submit_entry(self, slice: Slice, spy_price: float):
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain in current Slice")
            return

        chain = slice.OptionChains[self.option_symbol]
        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
        ]

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days away")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no qualifying call for expiration "
                f"{selected_expiry}"
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY crossover call entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={selected_expiry}, strike={selected.Strike}"
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and not self._ticket_finished(
            self.exit_ticket
        ):
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            return

        chain = slice.OptionChains[self.option_symbol]
        contract = next(
            (
                contract for contract in chain
                if contract.Symbol == self.held_option
            ),
            None
        )

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self._submit_option_liquidation(
                "50% profit target reached"
            )

    def _handle_expiration_processing(self):
        if self.held_option is None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date < expiry:
            return

        if self.expiration_processing_date != current_date:
            self.expiration_processing_date = current_date
            self.no_entry_date = current_date

            if self.entry_ticket is not None and not self._ticket_finished(
                self.entry_ticket
            ):
                self.entry_ticket.Cancel("Expiration processing")

            self._submit_option_liquidation(
                "Unexpected position at expiration processing"
            )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if not self.spy_liquidation_submitted:
            self.spy_liquidation_submitted = True
            self.no_entry_date = self.Time.date()

            self.Debug(
                f"Unexpected SPY equity position detected: {quantity}; "
                f"liquidating immediately"
