        self.equity_liquidation_date = None

    def OnData(self, slice: Slice):
        current_time = slice.Time
        current_date = current_time.date()

        self._handle_unexpected_spy_position(current_date)

        if self.held_symbol is not None:
            expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            # Never intentionally hold through expiration.
            if current_date >= expiry_date:
                self.blocked_entry_date = current_date
                self._submit_exit("expiration protection")
            else:
                prior_trading_day = self._previous_trading_day(expiry_date)

                if (
                    current_date == prior_trading_day
                    and current_time.hour == 15
                    and current_time.minute >= 45
                ):
                    self._submit_exit("expiration time stop")
                else:
                    self._check_profit_target(slice)

        spy_bar = None
        try:
            if slice.Bars.ContainsKey(self.spy_symbol):
                spy_bar = slice.Bars[self.spy_symbol]
        except Exception:
            try:
                spy_bar = slice.Bars.get(self.spy_symbol)
            except Exception:
                spy_bar = None

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        bar_date = bar_time.date()

        if not (
            bar_time.hour > 9
            or (bar_time.hour == 9 and bar_time.minute >= 30)
        ):
            return

        if bar_time.hour > 16 or (
            bar_time.hour == 16 and bar_time.minute > 0
        ):
            return

        session_start = bar_time.replace(hour=9, minute=30, second=0, microsecond=0)
        minutes_from_open = int((bar_time - session_start).total_seconds() // 60)
        bucket_number = minutes_from_open // 5
        new_bucket_start = session_start + timedelta(minutes=bucket_number * 5)

        if self.bucket_start is None:
            self.bucket_start = new_bucket_start

        if new_bucket_start != self.bucket_start:
            self._finalize_bucket(slice)
            self.bucket_start = new_bucket_start
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = bar

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if all(t in self.bucket_bars for t in expected_times):
            self._finalize_bucket(slice)
            self.bucket_start = None
            self.bucket_bars = {}

    def _finalize_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        # Missing five-minute data invalidates the entire consolidated bar.
        if not all(t in self.bucket_bars for t in expected_times):
            return

        bars = [self.bucket_bars[t] for t in expected_times]
        close = bars[-1].Close
        bar_end = self.bucket_start + timedelta(minutes=5)

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(float(close))

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        if not (
            (bar_end.hour == 9 and bar_end.minute >= 45)
            or (10 <= bar_end.hour <= 13)
            or (bar_end.hour == 14 and bar_end.minute <= 30)
        ):
            return

        if self.blocked_entry_date == slice.Time.date():
            return

        if self.held_symbol is not None or self._entry_order_is_open():
            return

        self._try_enter(slice, float(close))

    def _try_enter(self, slice: Slice, spy_price: float):
        chain = None

        try:
            if slice.OptionChains.ContainsKey(self.option_symbol):
                chain = slice.OptionChains[self.option_symbol]
        except Exception:
            try:
                chain = slice.OptionChains.get(self.option_symbol)
            except Exception:
                chain = None

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = slice.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(chain)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days out.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.held_symbol = selected.Symbol
        self.entry_fill_price = None
        self.entry_fill_quantity = 0
        self.entry_fill_value = 0

        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiry={selected.Expiry.date()}, strike={selected.Strike}"
        )

    def _check_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_fill_price is None:
            return

        if self.exit_ticket is not None:
            return

        quote_bar = None
        try:
            if slice.QuoteBars.ContainsKey(self.held_symbol):
                quote_bar = slice.QuoteBars[self.held_symbol]
        except Exception:
            try:
                quote_bar = slice.QuoteBars.get(self.held_symbol)
            except Exception:
                quote_bar = None

        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return

        bid = float(quote_bar.Bid.Close)
        ask = float(quote_bar.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_fill_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.entry_ticket is not None:
            status = self.entry_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                self.entry_ticket.Cancel("Exit requested")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}; symbol={self.held_symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        order_id = order_event.OrderId

        if self.entry_ticket is not None and order_id == self.entry_ticket.OrderId:
            if order_event.FillQuantity != 0:
                quantity = abs(order_event.FillQuantity)
                self.entry_fill_quantity += quantity
                self.entry_fill_value += quantity * float(order_event.FillPrice)
                self.entry_fill_price = (
                    self.entry_fill_value / self.entry_fill_quantity
                )

                self.Debug(
                    f"Entry filled: {self.held_symbol}; "
                    f"price={self.entry_fill_price:.4f}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Submitted,
            ) and order_event.Status != OrderStatus.Submitted:
                if order_event.Status != OrderStatus.Filled:
                    self.held_symbol = None
                    self.entry_fill_price = None
                self.entry_ticket = None

        if self.exit_ticket is not None and order_id == self.exit_ticket.OrderId:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
