            self.no_entry_date = None

        # Handle unexpected underlying equity created by exercise or assignment.
        if self.Portfolio[self.spy].Invested:
            if self.assignment_handled_date != today:
                self.Debug("Unexpected SPY exercise/assignment; liquidating SPY equity.")
                self.assignment_handled_date = today
            self.Liquidate(self.spy)
            self.no_entry_date = today

        self._process_expiration_rules(now)

