            return

        self._process_minute_bar(slice.Bars[self.spy], slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        minute_end = self.Time.replace(second=0, microsecond=0)
        session_open = datetime.combine(minute_end.date(), time(9, 30))
        session_close = datetime.combine(minute_end.date(), time(16, 0))

        if minute_end < session_open or minute_end > session_close:
            return

        elapsed_minutes = int((minute_end - session_open).total_seconds() / 60)
        bucket_index = (elapsed_minutes - 1) // 5
        bucket_end = session_open + timedelta(minutes=(bucket_index + 1) * 5)

        if self.last_minute_end == minute_end:
            return

        if self.bucket_end is None or bucket_end != self.bucket_end:
            self.bucket_end = bucket_end
            self.bucket_closes = []
            self.bucket_valid = (
                minute_end == bucket_end - timedelta(minutes=4)
            )
        elif (
            self.last_minute_end is not None
            and minute_end != self.last_minute_end + timedelta(minutes=1)
        ):
            self.bucket_valid = False

        self.bucket_closes.append(float(bar.Close))
        self.last_minute_end = minute_end

        if minute_end != self.bucket_end:
            return

        if self.bucket_valid and len(self.bucket_closes) == 5:
            close = self.bucket_closes[-1]
            self._process_five_minute_close(
                self.bucket_end,
                close,
                slice
            )

        self.bucket_end = None
        self.bucket_closes = []
        self.bucket_valid = True

    def _process_five_minute_close(self, bar_end, close, slice):
        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) > self.fast_period:
            self.fast_values.pop(0)

        if len(self.slow_values) > self.slow_period:
            self.slow_values.pop(0)

        current_fast = None
        current_slow = None

        if len(self.fast_values) == self.fast_period:
            current_fast = sum(self.fast_values) / self.fast_period

        if len(self.slow_values) == self.slow_period:
            current_slow = sum(self.slow_values) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        bar_time = bar_end.time()
        eligible = time(9, 45) <= bar_time <= time(14, 30)

        if eligible:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
