        if self.no_entry_date == today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        chain = self._get_option_chain(slice)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = None
        if self.spy in slice.Bars:
            current_price = float(slice.Bars[self.spy].Close)

        if current_price is None or current_price <= 0:
            current_price = float(self.Securities[self.spy].Price)

        if current_price <= 0:
            self.Debug("Skipped entry: invalid current SPY price.")
            return

        contracts = list(chain.Contracts.values())
        minimum_expiry = today + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days out.")
            return

        selected_expiry = expiries[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

    def _process_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        contract = self._get_held_contract(slice)

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _process_expiration_rules(self, now):
        if self.held_symbol is None or self.held_expiry is None:
            return

        today = now.date()

        # Prevent holding into expiration.
        if today >= self.held_expiry:
            self.no_entry_date = today
            self._submit_exit("expiration-day liquidation")
            return

        previous_day = self.held_expiry - timedelta(days=1)

        if today == previous_day and now.time() >= time(15, 45):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Exit requested.")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Submitted market exit: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected assignment order event; liquidating SPY.")
            self.no_entry_date = self.Time.date()
            self.Liquidate(self.spy)
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.held_symbol = self.entry_symbol
                self.held_expiry = self.Securities[
                    self.held_symbol
                ].Symbol.ID.Date.date()
                self.entry_price = float(order_event.FillPrice)

                self.Debug(
                    "Call entry filled: {0}, price {1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.FillQuantity != 0:
                self.Debug(
                    "Call exit filled: {0}, price {1}".format(
                        self.held_symbol,
                        order_event.FillPrice
                    )
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                if (
                    self.held_symbol is not None
                    and self.Portfolio[self.held_symbol].Quantity == 0
                ):
                    self.held_symbol = None
                    self.held_expiry = None
                    self.entry_price = None
                    self.entry_symbol = None
                self.exit_ticket = None

    def OnAssignmentOrder(self, assignment_event):
        self.Debug("Unexpected exercise/assignment; liquidating SPY equity.")
        self.no_entry_date = self.Time.date()
        self.Liquidate(self.spy)

    def _get_option_chain(self, slice: Slice):
        if slice.OptionChains is None:
            return None

        for symbol, chain in slice.OptionChains.items():
            if symbol == self.option.Symbol:
                return chain

        return None

    def _get_held_contract(self, slice: Slice):
        if self.held_symbol is None:
            return None

        if slice.OptionChains is None:
            return None

        for chain in slice.OptionChains.values():
            contract = chain.Contracts.get(self.held_symbol)
            if contract is not None:
                return contract

        return None

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )
