        self._process_expiration_rules(now)

        # Profit target is evaluated on every minute Slice.
        self._process_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        self._process_minute_bar(slice.Bars[self.spy], slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        minute_end = self.Time.replace(second=0, microsecond=0)
        session_open = datetime.combine(minute_end.date(), time(9, 30))
        session_close = datetime.combine(minute_end.date(), time(16, 0))

        if minute_end < session_open or minute_end > session_close:
            return

        elapsed_minutes = int((minute_end - session_open).total_seconds() / 60)
        bucket_index = (elapsed_minutes - 1) // 5
        bucket_end = session_open + timedelta(minutes=(bucket_index + 1) * 5)

        if self.last_minute_end == minute_end:
            return

        if self.bucket_end is None or bucket_end != self.bucket_end:
            self.bucket_end = bucket_end
            self.bucket_closes = []
            self.bucket_valid = (
                minute_end == bucket_end - timedelta(minutes=4)
            )
        elif (
            self.last_minute_end is not None
            and minute_end != self.last_minute_end + timedelta(minutes=1)
        ):
            self.bucket_valid = False

        self.bucket_closes.append(float(bar.Close))
        self.last_minute_end = minute_end

        if minute_end != self.bucket_end:
            return

        if self.bucket_valid and len(self.bucket_closes) == 5:
            close = self.bucket_closes[-1]
            self._process_five_minute_close(
                self.bucket_end,
                close,
                slice
            )

        self.bucket_end = None
        self.bucket_closes = []
        self.bucket_valid = True

    def _process_five_minute_close(self, bar_end, close, slice):
        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) > self.fast_period:
            self.fast_values.pop(0)

        if len(self.slow_values) > self.slow_period:
            self.slow_values.pop(0)

        current_fast = None
        current_slow = None

        if len(self.fast_values) == self.fast_period:
            current_fast = sum(self.fast_values) / self.fast_period

        if len(self.slow_values) == self.slow_period:
            current_slow = sum(self.slow_values) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        bar_time = bar_end.time()
        eligible = time(9, 45) <= bar_time <= time(14, 30)

        if eligible:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        chain = self._get_option_chain(slice)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = None
        if self.spy in slice.Bars:
            current_price = float(slice.Bars[self.spy].Close)

        if current_price is None or current_price <= 0:
            current_price = float(self.Securities[self.spy].Price)

        if current_price <= 0:
            self.Debug("Skipped entry: invalid current SPY price.")
            return

        contracts = list(chain.Contracts.values())
        minimum_expiry = today + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days out.")
            return

        selected_expiry = expiries[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

    def _process_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        contract = self._get_held_contract(slice)

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _process_expiration_rules(self, now):
        if self.held_symbol is None or self.held_expiry is None:
            return

        today = now.date()

        # Prevent holding into expiration.
        if today >= self.held_expiry:
            self.no_entry_date = today
            self._submit_exit("expiration-day liquidation")
            return

        previous_day = self.held_expiry - timedelta(days=1)

        if today == previous_day and now.time() >= time(15, 45):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Exit requested.")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Submitted market exit: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected assignment order event; liquidating SPY.")
            self.no_entry_date = self.Time.date()
