from AlgorithmImports import *

from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_values = {}
        self.minute_timestamp_is_end = None

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.time_stop_dates = set()
        self.no_entry_dates = set()

        self.equity_cleanup_ticket = None
        self.last_spy_price = None

    def OnData(self, slice: Slice):
        now = self.Time

        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            self._handle_expiration_and_time_stop(slice)

            if self._is_open_position():
                self._check_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self.last_spy_price = float(spy_bar.Close)
        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        timestamp = self.Time.replace(second=0, microsecond=0)

        if self.minute_timestamp_is_end is None:
            # LEAN data feeds may timestamp minute bars by start or end.
            # Detect the convention at the first regular-session bar.
            self.minute_timestamp_is_end = timestamp.minute != 30

        if not self.minute_timestamp_is_end:
            timestamp += timedelta(minutes=1)

        if timestamp.weekday() >= 5:
            return

        session_start = timestamp.replace(hour=9, minute=31)
        session_end = timestamp.replace(hour=16, minute=0)

        if timestamp < session_start or timestamp > session_end:
            return

        bucket_end_minute = ((timestamp.minute + 4) // 5) * 5
        bucket_end = timestamp.replace(minute=0) + timedelta(
            minutes=bucket_end_minute
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._discard_incomplete_bucket()

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_values = {}

        self.bucket_values[timestamp] = minute_bar

        if timestamp != bucket_end:
            return

        expected_minutes = [
            bucket_end - timedelta(minutes=i) for i in range(1, 6)
        ]

        if any(t not in self.bucket_values for t in expected_minutes):
            self._discard_incomplete_bucket()
            return

        close = float(minute_bar.Close)
        self._process_completed_five_minute_bar(bucket_end, close, slice)
        self._discard_incomplete_bucket()

    def _discard_incomplete_bucket(self):
        self.bucket_end = None
        self.bucket_values = {}

    def _process_completed_five_minute_bar(
        self,
        bar_end: datetime,
        close: float,
        slice: Slice
    ):
        previous_fast = self.previous_fast
        previous_slow = self.previous_slow

        self.closes.append(close)

        if len(self.closes) >= 5:
            current_fast = sum(list(self.closes)[-5:]) / 5.0
        else:
            current_fast = None

        if len(self.closes) >= 20:
            current_slow = sum(self.closes) / 20.0
        else:
            current_slow = None

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        eligible_time = (
            bar_end.hour > 9
            or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14
            or (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        if bullish_cross and eligible_time:
            self._try_entry(slice)

    def _try_entry(self, slice: Slice):
        today = self.Time.date()

        if today in self.no_entry_dates:
            return

        if self.held_symbol is not None and self._is_open_position():
            return

        if self._entry_order_is_open():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        spy_price = self.last_spy_price
        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped entry: invalid current SPY price.")
            return

        minimum_expiry = today + timedelta(days=7)

        candidates = []
        for contract in chain:
            expiry_date = self._contract_expiry_date(contract)

            if (
                expiry_date >= minimum_expiry
                and contract.Right == OptionRight.Call
            ):
                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no expiration satisfies the 7-day rule.")
            return

        nearest_expiry = min(
            self._contract_expiry_date(contract)
            for contract in candidates
        )

        strike_floor = 1.01 * spy_price
        strike_candidates = [
            contract
            for contract in candidates
            if (
                self._contract_expiry_date(contract) == nearest_expiry
                and contract.Strike >= strike_floor
            )
        ]

        if not strike_candidates:
            self.Debug(
                "Skipped entry: no call strike meets the 1% OTM requirement."
            )
            return

        selected = sorted(
            strike_candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute SMA crossover"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiry={nearest_expiry}; strike={selected.Strike}"
        )

    def _check_profit_target(self, slice: Slice):
        contract = self._find_contract_in_slice(slice, self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        ):
            self._submit_option_exit("50% profit target")

    def _handle_expiration_and_time_stop(self, slice: Slice):
        if self.held_symbol is None or not self._is_open_position():
            return

        expiry_date = self._contract_expiry_date_from_symbol(self.held_symbol)
        today = self.Time.date()

        if today >= expiry_date:
            self.no_entry_dates.add(today)
            self._submit_option_exit("expiration protection")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            today == previous_trading_day
            and self.Time.time() >= datetime.min.time().replace(
                hour=15,
                minute=45
            )
        ):
            self.time_stop_dates.add(today)
            self._submit_option_exit("pre-expiration time stop")

    def _submit_option_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self._ticket_is_terminal(
            self.exit_ticket
        ):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order.")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {self.held_symbol}; reason={reason}")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if (
            self.equity_cleanup_ticket is not None
            and not self._ticket_is_terminal(self.equity_cleanup_ticket)
        ):
            return

        self.Debug(
            f"Unexpected SPY equity position detected ({quantity}); "
            "liquidating immediately."
        )

        self.equity_cleanup_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment cleanup"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)

                self.Debug(
                    f"Entry filled: {self.held_symbol}; "
                    f"fill price={self.entry_price}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order canceled or invalid.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {self.exit_ticket.Symbol}; "
                    f"fill price={order_event.FillPrice}"
                )

                if self.Portfolio[self.exit_ticket.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

    def _find_contract_in_slice(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _is_open_position(self):
        return (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Quantity > 0
        )

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None
            and not self._ticket_is_terminal(self.entry_ticket)
        )

    @staticmethod
    def _ticket_is_terminal(ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    @staticmethod
    def _contract_expiry_date(contract):
        return contract.Symbol.ID.Date.date()

    @staticmethod
    def _contract_expiry_date_from_symbol(symbol):
        return symbol.ID.Date.date()

    def _previous_trading_day(self, date_value):
        date_value = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        ) - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            date_value
        ):
            date_value -= timedelta(days=1)

        return date_value.date()
