    def OnData(self, slice: Slice):
        now = self.Time
        current_date = now.date()

        self._handle_unexpected_spy_position()

        # Never intentionally carry an option into its expiration date.
        if self._held_option is not None:
            expiration_date = self._expiration_date(self._held_option)

            if current_date >= expiration_date:
                self._blocked_entry_date = current_date
                self._cancel_pending_entry()
                self._submit_option_exit("expiration processing")

            elif (
                now.hour == 15
                and now.minute == 45
