        # New York time, so use the current slice time as the minute end time.
        minute_end = now
        minute_start = minute_end - timedelta(minutes=1)

        if minute_start.hour < 9 or (
            minute_start.hour == 9 and minute_start.minute < 30
        ):
            return

        if minute_start.hour > 15 or (
            minute_start.hour == 15 and minute_start.minute >= 60
        ):
            return

        bucket_start = minute_start.replace(
            minute=(minute_start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self._bucket_start is None:
            self._bucket_start = bucket_start
            self._bucket_bars = [spy_bar]
            return

        if bucket_start != self._bucket_start:
            # Emit only complete five-minute bars. Missing minutes invalidate
            # the interval; no synthetic or forward-filled bar is created.
            if (
                len(self._bucket_bars) == 5
                and bucket_start == self._bucket_start + timedelta(minutes=5)
            ):
                completed = self._make_consolidated_bar(
                    self._bucket_start,
                    self._bucket_bars
                )
                self._on_five_minute_bar(completed, slice)

            self._bucket_start = bucket_start
            self._bucket_bars = [spy_bar]
        else:
