        open_price = bars[0].Open
        high_price = max(bar.High for bar in bars)
        low_price = min(bar.Low for bar in bars)
        close_price = bars[-1].Close
        volume = sum(int(bar.Volume) for bar in bars)

        return TradeBar(
            start,
            self.spy,
            open_price,
            high_price,
            low_price,
            close_price,
            volume,
            timedelta(minutes=5)
        )

    def _on_five_minute_bar(self, bar, slice):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if self.fast.IsReady else 0
        previous_slow = self.slow.Current.Value if self.slow.IsReady else 0

        self.fast.Update(IndicatorDataPoint(bar.EndTime, bar.Close))
        self.slow.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
