        for chain in chains:
            contracts.extend(list(chain))

        minimum_expiration = current_date + timedelta(days=7)

        eligible_expirations = sorted({
            self._expiration_date(contract.Symbol)
            for contract in contracts
            if self._expiration_date(contract.Symbol) >= minimum_expiration
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiration = eligible_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if (
                self._expiration_date(contract.Symbol) == selected_expiration
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish five-minute crossover entry"
        )

        self._entry_order_id = ticket.OrderId
        self.Debug(
            "Entry submitted: {0}, strike {1}, expiration {2}".format(
                selected.Symbol,
                selected.Strike,
                selected_expiration
            )
        )

    def _evaluate_profit_target(self, slice):
