                OrderStatus.PartiallyFilled
            ):
                self._held_option = order_event.Symbol
                self._entry_fill_price = order_event.FillPrice
                self._entry_order_id = None

                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_order_id = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self._exit_order_id = None
                self._held_option = None
                self._entry_fill_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._exit_order_id = None

        if order_event.OrderId == self._equity_cleanup_order_id:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._equity_cleanup_order_id = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            "Unexpected option exercise or assignment: {0}".format(
                assignment_event.Symbol
            )
        )
        self._handle_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0 or self._equity_cleanup_order_id is not None:
            return

        self.Debug(
            "Unexpected SPY equity position detected; liquidating entire position."
        )

        ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment cleanup"
        )
        self._equity_cleanup_order_id = ticket.OrderId

    def _cancel_pending_entry(self):
        if self._entry_order_id is not None:
            self.Transactions.CancelOrder(self._entry_order_id)
            self._entry_order_id = None

