        if self._entry_order_id is not None:
            self.Transactions.CancelOrder(self._entry_order_id)
            self._entry_order_id = None

    @staticmethod
    def _expiration_date(symbol):
        return symbol.ID.Date.date()

    def _is_trading_day_before(self, current_date, expiration_date):
        candidate = current_date + timedelta(days=1)

        while not self.spy_hours.IsDateOpen(candidate):
            candidate += timedelta(days=1)

        return candidate == expiration_date

