        )

    def GetHeldOptionSymbol(self):
        for security in self.Portfolio.Values:
            if (
                security.Invested
                and security.Symbol.SecurityType == self.spy_option.Symbol.SecurityType
            ):
                return security.Symbol
        return None

    def IsEntryOrderOpen(self):
        return (
            self.entry_ticket is not None
