from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyLongCallMovingAverageCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.fast = SimpleMovingAverage(self.fast_period)
        self.slow = SimpleMovingAverage(self.slow_period)

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end_minute = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None

        self.no_entry_date = None
        self.equity_liquidation_submitted = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.no_entry_date != current_date:
            self.no_entry_date = None
            self.equity_liquidation_submitted = False

        # Assignment/exercise protection.
        spy_holding = self.Portfolio[self.spy]
        if spy_holding.Quantity != 0:
            self.no_entry_date = current_date
            if not self.equity_liquidation_submitted:
                self.Debug(
                    f"{self.Time}: Unexpected SPY equity position detected; liquidating."
                )
                self.Liquidate(self.spy)
                self.equity_liquidation_submitted = True

        # Process the current minute's SPY bar.
        if self.spy in slice.Bars:
            minute_bar = slice.Bars[self.spy]
            five_minute = self._add_minute_bar(minute_bar)

            if five_minute is not None:
                self._process_five_minute_bar(
                    five_minute["end_time"],
                    five_minute["close"],
                    slice
                )

        # Never intentionally hold through expiration.
        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.no_entry_date = current_date
                self._submit_exit("expiration processing")
            elif self._is_expiration_eve(current_date, expiry_date):
                if self.Time.time() >= time(15, 45):
                    self._submit_exit("expiration-eve time stop")
            else:
                self._evaluate_profit_target(slice)

    def _add_minute_bar(self, bar):
        end_time = bar.EndTime
        local_date = end_time.date()
        total_minutes = end_time.hour * 60 + end_time.minute

        # Regular-session minute bars end from 09:31 through 16:00.
        if total_minutes < 9 * 60 + 31 or total_minutes > 16 * 60:
            return None

        bucket_end = ((total_minutes + 4) // 5) * 5

        if self.bucket_date != local_date:
            completed = self._finalize_bucket()
            self.bucket_date = local_date
            self.bucket_end_minute = bucket_end
            self.bucket_bars = {}
        elif self.bucket_end_minute != bucket_end:
            completed = self._finalize_bucket()
            self.bucket_end_minute = bucket_end
            self.bucket_bars = {}
        else:
            completed = None

        self.bucket_bars[total_minutes] = bar

        return completed

    def _finalize_bucket(self):
        if self.bucket_date is None or self.bucket_end_minute is None:
            return None

        expected = range(self.bucket_end_minute - 4, self.bucket_end_minute + 1)

        # Missing any minute means the five-minute bar is not produced.
        if any(minute not in self.bucket_bars for minute in expected):
            return None

        bars = [self.bucket_bars[minute] for minute in expected]
        return {
            "end_time": bars[-1].EndTime,
            "close": float(bars[-1].Close)
        }

    def _process_five_minute_bar(self, end_time, close, slice):
        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        if not self.fast.IsReady or not self.slow.IsReady:
            self.previous_fast = float(self.fast.Current.Value)
            self.previous_slow = float(self.slow.Current.Value)
            return

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
