                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self._on_five_minute_bar

        self.close_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False
        self.pending_signal_time = None

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_price = None

        self.held_symbol = None
        self.exit_ticket = None

        self.no_entry_date = None

    def _on_five_minute_bar(self, sender, bar):
        self.close_window.append(float(bar.Close))

        if len(self.close_window) < 20:
            return

        fast = sum(list(self.close_window)[-5:]) / 5.0
        slow = sum(self.close_window) / 20.0

        self.pending_signal = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )
        self.pending_signal_time = self.Time

        self.previous_fast = fast
        self.previous_slow = slow

    def OnData(self, slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position(today)
        self._handle_expiration_processing(today)

        if self.spy.Symbol in slice.Bars:
            self.consolidator.Update(slice.Bars[self.spy.Symbol])

        self._evaluate_profit_target(slice, today)
        self._evaluate_time_stop(today)

        if self.pending_signal:
            signal_time = self.pending_signal_time
            self.pending_signal = False
            self.pending_signal_time = None

            if (
                signal_time is not None
                and time(9, 45) <= signal_time.time() <= time(14, 30)
            ):
                self._try_enter(slice, today)

    def _try_enter(self, slice, today):
        if self.no_entry_date == today:
            return

        if self.held_symbol is not None:
            return

