        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()

            if today >= expiry:
                self.no_entry_date = today
                self._submit_exit("expiration liquidation")

        if (
            self.entry_ticket is not None
            and self._ticket_is_open(self.entry_ticket)
            and self.entry_ticket.Symbol.ID.Date.date() <= today
        ):
            self.no_entry_date = today
            self.entry_ticket.Cancel("Canceling entry during expiration processing.")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Canceling prior exit order.")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol}; reason={reason}")

    def _handle_unexpected_spy_position(self, today):
