            self.spy.Symbol,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )
        self.Debug(
            f"Unexpected SPY position detected; liquidating {quantity} shares."
        )

    def _preceding_trading_day(self, date):
        candidate = date - timedelta(days=1)

        while True:
            if candidate.weekday() < 5:
                try:
                    candidate_time = datetime.combine(candidate, time(0, 0))
                    if self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
                        candidate_time
                    ):
