                       .Expiration(0, 365)
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_price = None
        self.option_symbol = None
        self.exit_ticket = None

        self.pending_bar = None
        self.last_evaluated_bar_end = None
        self.no_entry_date = None

        self.Consolidate(
            self.spy,
            timedelta(minutes=5),
            self.OnFiveMinuteBar
        )

    def OnFiveMinuteBar(self, bar: TradeBar):
        if bar is None:
            return

        had_ready_averages = (
            self.fast_window.IsReady and self.slow_window.IsReady
        )

        previous_fast = (
            sum(self.fast_window) / self.fast_window.Count
            if had_ready_averages else None
        )
        previous_slow = (
            sum(self.slow_window) / self.slow_window.Count
            if had_ready_averages else None
        )

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        bullish_crossover = False
        if had_ready_averages and self.fast_window.IsReady and self.slow_window.IsReady:
            current_fast = sum(self.fast_window) / self.fast_window.Count
            current_slow = sum(self.slow_window) / self.slow_window.Count

            bullish_crossover = (
                previous_fast <= previous_slow
                and current_fast > current_slow
            )

        self.pending_bar = (bar, bullish_crossover)

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Handle unexpected assignment/exercise-created SPY holdings.
        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY equity position detected; liquidating.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
            self.no_entry_date = current_date

        # Manage an existing option position before considering entries.
        if self.option_symbol is not None and self.Portfolio[self.option_symbol].Invested:
            expiry_date = self.option_symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.no_entry_date = current_date
                self._submit_exit("expiration")
            elif self._is_time_stop_day(expiry_date) and self.Time.time() >= time(15, 45):
                self._submit_exit("time stop")
            else:
                self._check_profit_target(slice)

        # Evaluate each completed crossover bar once, using its current Slice.
        if self.pending_bar is not None:
            bar, bullish_crossover = self.pending_bar

            if (
                self.last_evaluated_bar_end != bar.EndTime
                and self.Time >= bar.EndTime
            ):
                self.last_evaluated_bar_end = bar.EndTime
                self.pending_bar = None

                bar_time = bar.EndTime.time()
                eligible_time = time(9, 45) <= bar_time <= time(14, 30)

                if bullish_crossover and eligible_time:
                    self._try_enter(slice, bar.Close)

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.no_entry_date == self.Time.date():
            return

        if self.option_symbol is not None and self.Portfolio[self.option_symbol].Invested:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped selection: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_chains = []

        for chain in chains:
            contracts = list(chain.Contracts.Values)
            if not contracts:
                continue

            expiries = [
                contract.Expiry.date()
                for contract in contracts
                if contract.Expiry.date() >= minimum_expiry
            ]
            if expiries:
                eligible_chains.append((min(expiries), contracts))

        if not eligible_chains:
            self.Debug("Skipped selection: no expiration at least seven days away.")
            return

        selected_expiry = min(item[0] for item in eligible_chains)

        candidates = []
        minimum_strike = spy_price * 1.01

        for expiry, contracts in eligible_chains:
            if expiry != selected_expiry:
                continue

            for contract in contracts:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() == selected_expiry
                    and contract.Strike >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId
        self.Debug(f"Call entry submitted: {selected.Symbol}")

    def _check_profit_target(self, slice: Slice):
        if self.option_symbol is None or self.entry_price is None:
            return

        if not slice.QuoteBars.ContainsKey(self.option_symbol):
            return

        quote = slice.QuoteBars[self.option_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _submit_exit(self, reason: str):
        if self.option_symbol is None:
            return

        quantity = self.Portfolio[self.option_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        if reason == "profit target":
            self.Debug("Profit target reached; canceling open exit orders.")

        self.exit_ticket = self.MarketOrder(
            self.option_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Option exit submitted: {reason}")

    def _is_time_stop_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while candidate >= self.Time.date() - timedelta(days=10):
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
                return self.Time.date() == candidate
            candidate -= timedelta(days=1)

        return False

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
            and order_event.Status == OrderStatus.Filled
        ):
            self.option_symbol = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                f"Call entry filled: {self.option_symbol}, "
                f"price={self.entry_price:.4f}"
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Option exit filled: {order_event.Symbol}")
            self.option_symbol = None
            self.entry_price = None
            self.exit_ticket = None

        if order_event.Status == OrderStatus.Assigned:
            self.Debug("Unexpected option assignment detected.")
            self.no_entry_date = self.Time.date()

            if self.Portfolio[self.spy].Invested:
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity
                )

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option exercise/assignment handling.")
        self.no_entry_date = self.Time.date()

        if self.Portfolio[self.spy].Invested:
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity
            )

from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_buckets = {}

        self.entry_ticket = None
        self.entry_order_id = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None

        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._liquidate_unexpected_spy()

        if self.held_symbol is not None:
            expiration_date = self.held_symbol.ID.Date.date()

            if self.Time.date() >= expiration_date:
                self.blocked_entry_date = self.Time.date()
                self._submit_exit("expiration processing")

        if (
            self.held_symbol is not None
            and self.Time.date() != self.blocked_entry_date
        ):
            self._evaluate_exits(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        consolidated = self._collect_minute(spy_bar)
        if consolidated is None:
            return

        close, bar_end = consolidated

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_time = bar_end.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if (
            bullish_crossover
            and eligible_time
            and self.Time.date() != self.blocked_entry_date
        ):
            self._try_entry(slice, spy_bar.Close)

    def _collect_minute(self, bar):
        minute_start = bar.EndTime - timedelta(minutes=1)
        clock = minute_start.time()

        if clock < time(9, 30) or clock >= time(16, 0):
            return None

        minutes_from_open = (
            minute_start.hour * 60 + minute_start.minute
        ) - (9 * 60 + 30)

        bucket_start = (
            minute_start.replace(second=0, microsecond=0)
            - timedelta(minutes=minutes_from_open % 5)
        )
        bucket_end = bucket_start + timedelta(minutes=5)

        bucket = self.minute_buckets.setdefault(bucket_start, {})
        bucket[minute_start] = bar

        if minute_start != bucket_end - timedelta(minutes=1):
            return None

        expected_minutes = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(minute not in bucket for minute in expected_minutes):
            self.minute_buckets.pop(bucket_start, None)
            return None

        bars = [bucket[minute] for minute in expected_minutes]
        self.minute_buckets.pop(bucket_start, None)

        return bars[-1].Close, bucket_end

    def _try_entry(self, slice: Slice, spy_price: float):
        if self.held_symbol is not None or self.entry_ticket is not None:
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(chain.Contracts.Values)

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 days out")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration"
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute SMA crossover"
        )
        self.entry_order_id = self.entry_ticket.OrderId

        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _evaluate_exits(self, slice: Slice):
        if (
            self.held_symbol is None
            or self.entry_price is None
            or self.exit_ticket is not None
        ):
            return

        contract = None
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is not None:
            contract = chain.Contracts.get(self.held_symbol)

        if (
            contract is not None
            and contract.BidPrice > 0
            and contract.AskPrice > 0
        ):
            midpoint = (contract.BidPrice + contract.AskPrice) / 2.0

            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("50% profit target")
                return

        if self.Time.time() >= time(15, 45):
            expiration_date = self.held_symbol.ID.Date.date()
            prior_trading_day = self._prior_trading_day(expiration_date)

            if self.Time.date() == prior_trading_day:
                self._submit_exit("expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {} ({})".format(
                self.held_symbol,
                reason
            )
        )

    def _prior_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _liquidate_unexpected_spy(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected SPY exercise or assignment position; liquidating"
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None

                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_order_id = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))

                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None

                self.exit_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option assignment; liquidating SPY")
        self._liquidate_unexpected_spy()

    def OnExerciseOrder(self, exercise_event):
        self.Debug("Unexpected option exercise; liquidating SPY")
        self._liquidate_unexpected_spy()

