from collections import deque
from datetime import datetime, timedelta, time

from AlgorithmImports import *


class SpyBullishCallStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        )

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)

        self.current_bucket_end = None
        self.current_bucket = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.no_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_expiration_processing()
        self._handle_unexpected_spy_position()

        self._evaluate_option_exit(slice)

        completed_bar = self._process_spy_minute_bar(slice)

        if completed_bar is not None:
            bar_end, close = completed_bar
            signal = self._update_averages_and_check_crossover(close)

            eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

            if signal and eligible_time:
                self._try_enter(slice, current_date)

    def _process_spy_minute_bar(self, slice: Slice):
        if self.spy.Symbol not in slice.Bars:
            return None

        bar = slice.Bars[self.spy.Symbol]
        bar_time = bar.Time
        bar_end = bar.EndTime

        if bar_time.date() != bar_end.date():
            return None

        if not (time(9, 30) <= bar_time.time() < time(16, 0)):
            return None

        session_start = datetime.combine(
            bar_end.date(),
            time(9, 35)
        )

        if bar_end < session_start:
            return None

        bucket_number = int(
            (bar_end - session_start).total_seconds() // 300
        )
        bucket_end = session_start + timedelta(minutes=5 * bucket_number)

        completed = None

        if (
            self.current_bucket_end is not None
            and bucket_end != self.current_bucket_end
        ):
            completed = self._complete_bucket()
            self.current_bucket = []

        self.current_bucket_end = bucket_end
        self.current_bucket.append(bar)

        return completed

    def _complete_bucket(self):
        if not self.current_bucket:
            return None

        bars = sorted(self.current_bucket, key=lambda x: x.EndTime)

        # Do not create a bar from an incomplete five-minute interval.
        if len(bars) != 5:
            return None

        close = bars[-1].Close
        return self.current_bucket_end, close

    def _update_averages_and_check_crossover(self, close):
        previous_fast = None
        previous_slow = None

        if len(self.slow_closes) == 20:
            previous_fast = sum(list(self.slow_closes)[-5:]) / 5.0
            previous_slow = sum(self.slow_closes) / 20.0

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return False

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        if previous_fast is None or previous_slow is None:
            return False

        return (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

    def _try_enter(self, slice: Slice, current_date):
        if self.no_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        chain = None

        for _, candidate_chain in slice.OptionChains.items():
            if candidate_chain.Symbol == self.spy_option.Symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_price = self.Securities[self.spy.Symbol].Price

        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        eligible_contracts = [
            contract
            for contract in chain.Contracts.Values
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible_contracts:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiry = min(
            contract.Expiry.date()
            for contract in eligible_contracts
        )

        strike_floor = current_price * 1.01

        candidates = [
            contract
            for contract in eligible_contracts
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= strike_floor
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"expiry={selected.Expiry.date()}, strike={selected.Strike}"
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity <= 0:
            return

        contract = None

        for _, chain in slice.OptionChains.items():
            if self.held_symbol in chain.Contracts:
                contract = chain.Contracts[self.held_symbol]
                break

        if contract is not None:
            bid = contract.BidPrice
            ask = contract.AskPrice

            if (
                bid is not None
                and ask is not None
                and bid > 0
                and ask > 0
                and self.entry_price is not None
            ):
                midpoint = (bid + ask) / 2.0

                if midpoint >= 1.50 * self.entry_price:
                    self._submit_exit("profit target")
                    return

        expiry_date = self.held_symbol.ID.Date.date()
        preceding_trading_day = self._previous_trading_day(expiry_date)

        if (
            self.Time.date() == preceding_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")

    def _handle_expiration_processing(self):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            self._submit_exit("expiration processing")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )

        self.Debug(
            f"Exit submitted: {self.held_symbol.Value}, reason={reason}"
        )

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy.Symbol].Quantity

        if spy_quantity == 0:
            return

        self.no_entry_date = self.Time.date()

        if not self._ticket_is_open(self.equity_liquidation_ticket):
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy.Symbol,
                -spy_quantity
            )
            self.Debug(
                f"Unexpected SPY exercise/assignment position; "
                f"liquidating {spy_quantity} shares."
            )

    def OnAssignmentOrderEvent(self, assignment_event):
        self.no_entry_date = self.Time.date()
