        self.previous_fast = None
        self.previous_slow = None

        self.current_interval_start = None
        self.current_minute_closes = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.entry_filled_quantity = 0
        self.exit_submitted = False

        self.block_entries_today = False
        self.equity_liquidation_submitted = False
        self.last_assignment_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.last_assignment_date != today:
            self.block_entries_today = False
            self.equity_liquidation_submitted = False
            self.last_assignment_date = today

        self._handle_unexpected_spy_position()
        self._process_option_exit_rules(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        start = bar.Time
        end = bar.EndTime

        if start.date() != end.date():
            return

        session_start = start.replace(hour=9, minute=30, second=0, microsecond=0)
        session_end = start.replace(hour=16, minute=0, second=0, microsecond=0)

        if start < session_start or end > session_end:
            return

        interval_start = start.replace(
            minute=(start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if (
            self.current_interval_start is not None
            and interval_start != self.current_interval_start
        ):
            self._complete_interval()

        if self.current_interval_start is None:
            self.current_interval_start = interval_start
            self.current_minute_closes = {}

        if interval_start != self.current_interval_start:
            self.current_interval_start = interval_start
            self.current_minute_closes = {}

        self.current_minute_closes[start] = float(bar.Close)

        if len(self.current_minute_closes) == 5:
            self._complete_interval()

    def _complete_interval(self):
        if self.current_interval_start is None:
            return

        interval_start = self.current_interval_start
        interval_end = interval_start + timedelta(minutes=5)

        expected_times = [
            interval_start + timedelta(minutes=i)
            for i in range(5)
        ]

        valid = (
            len(self.current_minute_closes) == 5
            and all(t in self.current_minute_closes for t in expected_times)
        )

        closes = self.current_minute_closes
        self.current_interval_start = None
        self.current_minute_closes = {}

        if not valid:
            return

        close = closes[expected_times[-1]]
        self.close_window.append(close)

        if len(self.close_window) > 20:
            self.close_window.pop(0)

        if len(self.close_window) < 20:
            return

        fast = sum(self.close_window[-5:]) / 5.0
        slow = sum(self.close_window[-20:]) / 20.0

        if self.previous_fast is not None and self.previous_slow is not None:
            bullish_cross = (
                self.previous_fast <= self.previous_slow
                and fast > slow
            )

            eligible_time = (
                interval_end.time() >= datetime.strptime(
                    "09:45", "%H:%M"
                ).time()
                and interval_end.time() <= datetime.strptime(
                    "14:30", "%H:%M"
                ).time()
            )

            if bullish_cross and eligible_time:
                self._try_enter()

        self.previous_fast = fast
        self.previous_slow = slow

    def _try_enter(self):
        today = self.Time.date()

        if self.block_entries_today:
            return

        if self.entry_ticket is not None:
            return

        if self._held_option_symbol() is not None:
            return

        chains = list(self.CurrentSlice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date()
            for contract in candidates
        )

        underlying_price = float(self.Securities[self.spy].Price)
        minimum_strike = underlying_price * 1.01

        strikes = [
            contract for contract in candidates
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Strike >= minimum_strike
            )
        ]

        if not strikes:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        selected = min(
            strikes,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.entry_price = None
        self.entry_filled_quantity = 0

    def _process_option_exit_rules(self, slice: Slice):
        symbol = self._held_option_symbol()
        if symbol is None:
            return

        holding = self.Portfolio[symbol]
        quantity = holding.Quantity
        if quantity <= 0:
            return

        security = self.Securities[symbol]
        expiry_date = security.Symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.block_entries_today = True
            self._submit_exit(symbol, quantity, "Expiration protection")
            return

        stop_date = self._previous_trading_day(expiry_date)

        if (
            today == stop_date
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit(symbol, quantity, "Pre-expiration time stop")
            return

        if self.exit_submitted or self.entry_price is None:
            return

        quote = self._current_option_quote(slice, symbol)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit(symbol, quantity, "50 percent profit target")

    def _current_option_quote(self, slice: Slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue

                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    return bid, ask

                return None

        return None

    def _submit_exit(self, symbol, quantity, reason):
        if self.exit_submitted:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            ):
                self.Transactions.CancelOrder(
                    self.exit_ticket.OrderId,
                    "Replacing open exit order"
                )

        self.exit_ticket = self.MarketOrder(
            symbol,
            -abs(quantity),
            tag=reason
        )
        self.exit_submitted = True
        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.IsAssignment:
            self.Debug("Unexpected option assignment or exercise detected.")
            self.block_entries_today = True
            self._liquidate_spy_equity()

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.PartiallyFilled,
                    OrderStatus.Filled
                ):
                    fill_quantity = abs(order_event.FillQuantity)

                    if fill_quantity > 0:
                        total_value = (
                            self.entry_price * self.entry_filled_quantity
                            if self.entry_price is not None else 0.0
                        )
                        total_value += (
                            float(order_event.FillPrice) * fill_quantity
                        )
                        self.entry_filled_quantity += fill_quantity
                        self.entry_price = (
                            total_value / self.entry_filled_quantity
                        )

                    if order_event.Status == OrderStatus.Filled:
                        self.Debug(
                            "Call entry filled at "
                            + str(self.entry_price)
                        )

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None
                    self.entry_price = None
                    self.entry_filled_quantity = 0

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Option exit filled.")
                    self.exit_ticket = None
                    self.exit_submitted = False
                    self.entry_ticket = None
                    self.entry_price = None
                    self.entry_filled_quantity = 0

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None
                    self.exit_submitted = False

    def OnAssignmentOrderEvent(self, assignment_order_event):
        self.Debug("Unexpected assignment order event detected.")
        self.block_entries_today = True
        self._liquidate_spy_equity()

    def _held_option_symbol(self):
        for security in self.Portfolio.Values:
            symbol = security.Symbol

            if (
                symbol.SecurityType == SecurityType.Option
                and security.Quantity > 0
                and symbol.Underlying == self.spy
            ):
                return symbol

        return None

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.block_entries_today = True
            self._liquidate_spy_equity()

    def _liquidate_spy_equity(self):
        if self.equity_liquidation_submitted:
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected SPY equity from exercise or assignment"
        )
        self.equity_liquidation_submitted = True

    def _previous_trading_day(self, date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate
