from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.last_spy_price = None
        self.pending_signal = False

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_filled_quantity = 0
        self.entry_cost = 0
        self.entry_price = None

        self.held_symbol = None
        self.exit_ticket = None
        self.time_stop_date = None
        self.expiration_processing_date = None
        self.equity_liquidation_ticket = None

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        bar_time = bar.EndTime.time()

        # Regular-session five-minute bars only.
        if bar_time < time(9, 30) or bar_time > time(16, 0):
            return

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        # Missing intervals naturally produce no consolidated bar and therefore
        # do not update either moving average.
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if (
            eligible_time
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            self.pending_signal = True

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Immediately remove unexpected SPY equity created by exercise/assignment.
        if self.Portfolio[self.spy].Quantity != 0:
            if (
                self.equity_liquidation_ticket is None
                or not self._is_open(self.equity_liquidation_ticket)
            ):
                self.Debug("Unexpected SPY equity position detected; liquidating.")
                self.equity_liquidation_ticket = self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="Unexpected exercise/assignment liquidation"
                )

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self.last_spy_price = spy_bar.Close

        # Expiration processing and scheduled time stop take precedence.
        if self.held_symbol is not None:
            expiry_date = self._held_expiry_date()

            if expiry_date is not None and today >= expiry_date:
                self.expiration_processing_date = today
                self._submit_exit("Expiration protection")
            elif self._is_immediately_preceding_trading_day(expiry_date):
                if self.Time.time() >= time(15, 45):
                    self._submit_exit("Pre-expiration time stop")

        # Profit target is evaluated on every minute Slice.
        if self.held_symbol is not None and self.exit_ticket is None:
            contract = self._current_contract(slice, self.held_symbol)

            if contract is not None:
                bid = getattr(contract, "BidPrice", 0)
                ask = getattr(contract, "AskPrice", 0)

                if bid > 0 and ask > 0 and self.entry_price is not None:
                    midpoint = (bid + ask) / 2.0

                    if midpoint >= 1.50 * self.entry_price:
                        self._cancel_exit_orders()
                        self._submit_exit("50 percent profit target")

        # Never open a replacement on expiration-processing days.
        if self.pending_signal:
            self.pending_signal = False

            if (
                self.held_symbol is None
                and self.entry_ticket is None
                and self.expiration_processing_date != today
                and self.Portfolio[self.spy].Quantity == 0
            ):
                self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        chain = slice.OptionChains.get(self.option)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = self.last_spy_price
        if current_price is None or current_price <= 0:
            self.Debug("Skipped entry: no valid current SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        contracts = list(chain)
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_filled_quantity = 0
        self.entry_cost = 0
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute SMA crossover"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiry={selected_expiry}; strike={selected.Strike}"
        )

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self._cancel_exit_orders()

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol}; reason={reason}")

    def _cancel_exit_orders(self):
        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Canceled before replacement exit order")
        self.exit_ticket = None

    def _current_contract(self, slice: Slice, symbol: Symbol):
        chain = slice.OptionChains.get(self.option)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                return contract

        return None

    def _held_expiry_date(self):
        if self.held_symbol is None:
            return None

        security = self.Securities.get(self.held_symbol)
        if security is None:
            return None

        return security.Symbol.ID.Date.date()

    def _is_immediately_preceding_trading_day(self, expiry_date):
        if expiry_date is None:
            return False

        candidate = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return self.Time.date() == candidate

    @staticmethod
    def _is_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        message = str(getattr(order_event, "Message", "")).lower()
        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        is_exercise_or_assignment = (
            is_assignment
            or "assign" in message
            or "exercis" in message
        )

        if is_exercise_or_assignment:
            self.Debug(
                f"Unexpected exercise/assignment handling: "
                f"{order_event.Symbol}"
            )

            if self.Portfolio[self.spy].Quantity != 0:
                self.equity_liquidation_ticket = self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="Unexpected exercise/assignment liquidation"
                )

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            ):
                fill_quantity = abs(order_event.FillQuantity)

                if fill_quantity > 0:
                    self.entry_filled_quantity += fill_quantity
                    self.entry_cost += fill_quantity * order_event.FillPrice
                    self.entry_price = (
                        self.entry_cost / self.entry_filled_quantity
                    )
                    self.held_symbol = self.entry_symbol

                    if order_event.Status == OrderStatus.Filled:
                        self.Debug(
                            f"Entry filled: {self.held_symbol}; "
                            f"price={self.entry_price}"
                        )
                        self.entry_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order canceled or invalid.")
                self.entry_ticket = None
                self.entry_symbol = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_ticket = None

                if self.held_symbol is not None:
                    if self.Portfolio[self.held_symbol].Quantity == 0:
                        self.held_symbol = None
                        self.entry_symbol = None
                        self.entry_price = None
                        self.entry_filled_quantity = 0
                        self.entry_cost = 0

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

from datetime import datetime, timedelta, time

from AlgorithmImports import *


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        spy_security = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        )
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security.Symbol

        option_security = self.AddOption("SPY", Resolution.Minute)
        option_security.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = option_security.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_date = None
        self._bucket_end = None
        self._minute_bars = {}

        self._signal_pending = False
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_option = None
        self._entry_price = None
        self._entry_quantity = 0
        self._no_entry_date = None

        self._equity_liquidation_submitted = False

    def OnData(self, data: Slice):
        today = self.Time.date()

        # Handle unexpected SPY equity created by exercise or assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            if not self._equity_liquidation_submitted:
                self.Debug(
                    f"Unexpected SPY equity position detected: "
                    f"{spy_quantity}; liquidating."
                )
                self.MarketOrder(self.spy, -spy_quantity)
                self._equity_liquidation_submitted = True
        else:
            self._equity_liquidation_submitted = False

        # Expiration processing begins on the expiration date.
        if self._held_option is not None:
            expiry_date = self._held_option.ID.Date.date()

            if today >= expiry_date:
                self._no_entry_date = today
                self._submit_exit("expiration processing")
            else:
                self._evaluate_option_exit(data)

        # Build a five-minute bar from actual minute bars only.
        minute_bar = data.Bars.get(self.spy)
        if minute_bar is not None:
            self._accept_minute_bar(minute_bar)

        # Evaluate a signal exactly once using the Slice containing the
        # completed five-minute bar.
        if self._signal_pending:
            self._signal_pending = False

            if (
                self._entry_ticket is None
                and self._held_option is None
                and self._no_entry_date != today
            ):
                self._try_enter(data)

    def _accept_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        bar_date = end_time.date()

        if self._bucket_date != bar_date:
            self._bucket_date = bar_date
            self._bucket_end = None
            self._minute_bars = {}

        base_minutes = 9 * 60 + 30
        end_minutes = end_time.hour * 60 + end_time.minute

        if end_minutes < base_minutes:
            return

        bucket_number = (end_minutes - base_minutes + 4) // 5
        bucket_end = datetime.combine(
            bar_date,
            time(0, 0)
        ) + timedelta(minutes=base_minutes + bucket_number * 5)

        if self._bucket_end is None:
            self._bucket_end = bucket_end
        elif bucket_end != self._bucket_end:
            self._finish_bucket()
            self._bucket_end = bucket_end
            self._minute_bars = {}

        self._minute_bars[end_time] = bar

        if end_time == self._bucket_end:
            self._finish_bucket()

    def _finish_bucket(self):
        if self._bucket_end is None:
            return

        expected = [
            self._bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if all(t in self._minute_bars for t in expected):
            close = self._minute_bars[expected[-1]].Close
            self._update_five_minute_averages(self._bucket_end, close)

        # Never carry missing-minute data into another interval.
        self._minute_bars = {}

    def _update_five_minute_averages(self, end_time, close):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        if (
            previous_fast is None
            or previous_slow is None
            or not self.fast.IsReady
            or not self.slow.IsReady
        ):
            return

        eligible_start = time(9, 45)
        eligible_end = time(14, 30)
        bar_end_time = end_time.time()

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if (
            bullish_cross
            and eligible_start <= bar_end_time <= eligible_end
        ):
            self._signal_pending = True

    def _try_enter(self, data: Slice):
        chain = data.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        spy_bar = data.Bars.get(self.spy)
        spy_price = (
            spy_bar.Close
            if spy_bar is not None
            else self.Securities[self.spy].Price
        )

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no qualifying call for "
                f"{selected_expiry}."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _evaluate_option_exit(self, data: Slice):
        if self._held_option is None or self._entry_price is None:
            return

        today = self.Time.date()
        expiry_date = self._held_option.ID.Date.date()

        # Time stop at 15:45 on the trading day immediately preceding expiry.
        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")
            return

        chain = data.OptionChains.get(self.option_symbol)
