        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._minute_bucket = None
        self._bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_date = None
        self._assignment_debugged = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._liquidate_unexpected_spy_position()
        self._process_expiration_safety()

        completed_bar = self._accumulate_spy_minute_bar(slice)

        if completed_bar is not None:
            self._process_five_minute_bar(completed_bar, slice)

        self._evaluate_profit_target(slice)
        self._evaluate_time_stop()

    def _accumulate_spy_minute_bar(self, slice):
        if self.spy.Symbol not in slice.Bars:
            return None

        minute_bar = slice.Bars[self.spy.Symbol]
        bar_time = minute_bar.Time
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return None

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        completed = None

        if self._minute_bucket is not None and bucket_start != self._minute_bucket:
            completed = self._complete_bucket(self._minute_bucket)

        if self._minute_bucket != bucket_start:
            self._minute_bucket = bucket_start
            self._bucket_bars = {}

        self._bucket_bars[bar_time] = minute_bar
        return completed

    def _complete_bucket(self, bucket_start):
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self._bucket_bars for t in expected_times):
            self._bucket_bars = {}
            return None

        bars = [self._bucket_bars[t] for t in expected_times]

        consolidated = TradeBar(
            bucket_start,
            self.spy.Symbol,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self._bucket_bars = {}
        return consolidated

